,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C774 \D398\C774\C9C0\B294 \C790\B3D9\D654 \B85C\ADF8\C5D0 \B300\D55C \B300\D654\C2DD \BCF4\ACE0\C11C\B97C \C81C\ACF5\D569\B2C8\B2E4.</p>'),
unistr('<p>\C774\C804 \C790\B3D9\D654 \C2E4\D589\C5D0 \B300\D574 \AE30\B85D\B41C \C815\BCF4\B97C \AC80\D1A0\D569\B2C8\B2E4. \B85C\ADF8\C5D0\B294 \C2DC\C791 \BC0F \C885\B8CC \C2DC\AC04\AE30\B85D\C740 \BB3C\B860 \CC98\B9AC\B41C \D589\C5D0 \B300\D55C \C138\BD80\C815\BCF4(\C131\ACF5 \BC0F \C624\B958 \D3EC\D568)\AC00 \D3EC\D568\B418\C5B4 \C788\C2B5\B2C8\B2E4. \CC98\B9AC\B41C \D589\C5D0 \B300\D55C \AC1C\BCC4 \BA54\C2DC\C9C0\B97C \BCF4\B824\BA74 \BA54\C2DC\C9C0\B85C \B4DC\B9B4\B2E4\C6B4\D569\B2C8\B2E4.</p>'),
''))
,p_version_scn=>2565321
);
