,p_name=>'PE.PROPERTY.AI_SYSTEM_PROMPT.EXAMPLES'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\ADC0\D558\B294 \B9C8\CF00\D305 \C804\BB38\AC00\C785\B2C8\B2E4. \C81C\D488 \C124\BA85\ACFC \C2DC\B4DC \B2E8\C5B4\AC00 \C81C\ACF5\B418\BA70, \ADC0\D558\C758 \D0DC\C2A4\D06C\B294 \C81C\D488\BA85\C744 \C0DD\C131\D558\B294 \AC83\C785\B2C8\B2E4.</p>'),
unistr('<p>\ADC0\D558\B294 \C804\BB38 \BC88\C5ED\AC00\C785\B2C8\B2E4. \C601\C5B4\B85C \B41C \BB38\C7A5\C774 \C81C\ACF5\B418\BA70, \ADC0\D558\C758 \D0DC\C2A4\D06C\B294 \D574\B2F9 \BB38\C7A5\C744 \D504\B791\C2A4\C5B4\B85C \BC88\C5ED\D558\B294 \AC83\C785\B2C8\B2E4.</p>')))
,p_version_scn=>2565267
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(114005946578665063)
,p_name=>'PE.PROPERTY.AI_SYSTEM_PROMPT.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>AI \C11C\BE44\C2A4\C5D0 \B300\D55C \CD08\AE30 \C9C0\CE68 \B610\B294 \CEE8\D14D\C2A4\D2B8\B97C \C9C0\C815\D569\B2C8\B2E4. \C798 \B9CC\B4E4\C5B4\C9C4 \C2DC\C2A4\D15C \D504\B86C\D504\D2B8\B294 AI\C758 \B3D9\C791\C744 \C548\B0B4\D558\ACE0 AI\C758 \C751\B2F5 \D1A4\C744 \C124\C815\D569\B2C8\B2E4.'),
unistr('\D6A8\ACFC\C801\C778 \C2DC\C2A4\D15C \D504\B86C\D504\D2B8\B97C \C0DD\C131\D558\B824\BA74 AI\AC00 \B9E1\C744 \B864 \B610\B294 \C804\BB38 \C9C0\C2DD\C744 \BA85\D655\D558\AC8C \C815\C758\D558\B294 \AC83\BD80\D130 \C2DC\C791\D569\B2C8\B2E4. \B2E4\C74C\C73C\B85C, \C608\C0C1\B418\B294 AI\C758 \D2B9\C815 \D0DC\C2A4\D06C \B610\B294 \C751\B2F5 \C720\D615\C744 \C124\BA85\D569\B2C8\B2E4.</p>'),
unistr('<p>\CC38\ACE0: \D6A8\ACFC\C801\C778 \C2DC\C2A4\D15C \D504\B86C\D504\D2B8 \C0DD\C131 \BC29\BC95\C744 \BAA8\B97C \ACBD\C6B0 AI \C11C\BE44\C2A4 \C124\BA85\C11C\C5D0\C11C \C790\C138\D55C \C9C0\CE68\C744 \CC38\C870\D558\C2ED\C2DC\C624. \B610\D55C \C0DD\C131\D615 AI \C2DC\C2A4\D15C\C5D0 \D504\B86C\D504\D2B8 \C791\C131\C5D0 \B300\D55C \B3C4\C6C0\C744 \C694\CCAD\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('\C608\B97C \B4E4\C5B4, <em>"\C81C\ACF5\B41C \D14D\C2A4\D2B8\C5D0\C11C \AD00\B828 \D0DC\ADF8\B098 \D0A4\C6CC\B4DC\B97C \CD94\CD9C\D558\B294 \D0DC\C2A4\D06C\B97C \B9E1\C740 AI \B3C4\C6B0\BBF8\B97C \C704\D55C \C2DC\C2A4\D15C \D504\B86C\D504\D2B8 \C791\C131\C744 \B3C4\C640\C8FC\C138\C694"</em>\B77C\ACE0 \C694\CCAD\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>')))
,p_version_scn=>2565250
);
