,p_name=>'PE.PROPERTY.BROWSER_CACHE.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\CE90\C2DC\AC00 \C0AC\C6A9\C73C\B85C \C124\C815\B41C \ACBD\C6B0 \BE0C\B77C\C6B0\C800\AC00 \CE90\C2DC(\BA54\BAA8\B9AC \BC0F \B514\C2A4\D06C)\C5D0 \C560\D50C\B9AC\CF00\C774\C158 \D398\C774\C9C0\C758 \CF58\D150\CE20\B97C \C800\C7A5\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('\C0AC\C6A9\C790\AC00 \BE0C\B77C\C6B0\C800\C5D0\C11C \B4A4\B85C \B2E8\CD94\B97C \B204\B974\BA74 \D398\C774\C9C0\AC00 \C11C\BC84\C5D0\C11C \B85C\B4DC\B418\C9C0 \C54A\ACE0 \C77C\BC18\C801\C73C\B85C \CE90\C2DC\C5D0\C11C \B85C\B4DC\B429\B2C8\B2E4.'),
unistr('\CE90\C2DC\AC00 \C0AC\C6A9 \C548\D568\C73C\B85C \C124\C815\B418\BA74 \BE0C\B77C\C6B0\C800\AC00 \D398\C774\C9C0 \CF58\D150\CE20\B97C \C800\C7A5\D558\C9C0 \C54A\B3C4\B85D \C9C0\C815\B418\ACE0, \BE0C\B77C\C6B0\C800\AC00 \C11C\BC84\C5D0\C11C \D398\C774\C9C0\B97C \C0C8\B85C \C694\CCAD\D569\B2C8\B2E4.</p>'),
unistr('<p>Oracle\C740 \BCF4\C548 \AD00\C810\C5D0\C11C \CE90\C2DC\B97C \C0AC\C6A9 \C548\D568\C73C\B85C \C124\C815\D574\C11C \BE0C\B77C\C6B0\C800\AC00 \BBFC\AC10\D55C \B370\C774\D130\B97C \C800\C7A5\D558\C9C0 \C54A\ACE0 URL\C774 \BCC0\ACBD\B420 \ACBD\C6B0 \D56D\C0C1 \D398\C774\C9C0\B97C \C694\CCAD\D558\B3C4\B85D \D560 \AC83\C744 \AD8C\C7A5\D569\B2C8\B2E4.'),
unistr('\ADF8\B807\C9C0 \C54A\C73C\BA74 \B85C\ADF8\C544\C6C3\D55C \D6C4\C5D0\B3C4 \BE0C\B77C\C6B0\C800 \B0B4\C5ED\C5D0\C11C \B4A4\B85C \C774\B3D9\D558\C5EC \C774\C804 \C138\C158\C5D0\C11C \CE90\C2DC\C5D0 \C800\C7A5\B41C \CF58\D150\CE20\B97C \D655\C778\D560 \C218\B3C4 \C788\C2B5\B2C8\B2E4.'),
unistr('\BE0C\B77C\C6B0\C800 \CE90\C2DC\B97C \C0AC\C6A9 \C548\D568\C73C\B85C \C124\C815\D558\BA74 \B300\D654\C2DD \BCF4\ACE0\C11C\C640 \AC19\C774 \BD80\BD84 \D398\C774\C9C0 \C0C8\B85C\ACE0\CE68\C744 \C0AC\C6A9\D558\B294 \D398\C774\C9C0\C640 \AD00\B828\D574\C11C \CC3E\AE30 \C5B4\B824\C6B4 \B4A4\B85C \B2E8\CD94 \BB38\C81C\B97C \BC29\C9C0\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
unistr('<p>\C774 \C18D\C131\C774 <strong>\C0AC\C6A9 \C548\D568</strong>\C73C\B85C \C124\C815\B418\C5B4 \C788\B294 \ACBD\C6B0 &PRODUCT_NAME.\C740(\B294) \D398\C774\C9C0 \CF58\D150\CE20\B97C \B514\C2A4\D06C \B610\B294 \BA54\BAA8\B9AC\C758 \CE90\C2DC\C5D0 \C800\C7A5\D558\C9C0 \C54A\B3C4\B85D \BE0C\B77C\C6B0\C800\C5D0 \C9C0\C815\D558\B294 HTTP \D5E4\B354 <em>cache-control: no-store</em>\B97C \C804\C1A1\D569\B2C8\B2E4.'),
unistr('<strong>\C560\D50C\B9AC\CF00\C774\C158 \AE30\BCF8\AC12</strong>\C73C\B85C \C124\C815\B41C \ACBD\C6B0, \C560\D50C\B9AC\CF00\C774\C158\C758 <em>\BE0C\B77C\C6B0\C800 \CE90\C2DC</em> \C18D\C131\C5D0\C11C \B7F0\D0C0\C784\C5D0 \AC12\C744 \AC00\C838\C635\B2C8\B2E4.</p>'),
unistr('<p>\CC38\ACE0: \C774 \AE30\B2A5\C744 \C0AC\C6A9\D558\B824\BA74 HTTP \D5E4\B354 \C751\B2F5 \BCC0\C218\C778 <code>cache-control</code>\C744 \C9C0\C6D0\D558\B294 \CD5C\C2E0 \BE0C\B77C\C6B0\C800\AC00 \D544\C694\D569\B2C8\B2E4.')))
,p_version_scn=>2565330
);
