,p_name=>'PE.PROPERTY.BUILD_OPTION.EXAMPLES'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>1. \B9CE\C740 \C124\CE58\B97C \D3EC\D568\D560 \C560\D50C\B9AC\CF00\C774\C158\C744 \AC1C\BC1C\D558\ACE0 \C788\C2B5\B2C8\B2E4.'),
unistr('                                        \B610\D55C \AC01 \C124\CE58\C5D0\C11C\B294 \D2B9\C815 \C560\D50C\B9AC\CF00\C774\C158 \AE30\B2A5\C744 \C0AC\C6A9 \B610\B294 \C0AC\C6A9 \C548\D568\C73C\B85C \C124\C815\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('                                        \BE4C\B4DC \C635\C158\C744 \C0AC\C6A9\D558\C5EC \C560\D50C\B9AC\CF00\C774\C158\C744 \AC1C\BC1C\D560 \C218 \C788\C2B5\B2C8\B2E4. \C124\CE58\B41C \ACBD\C6B0 \C5F0\ACB0\B41C \C560\D50C\B9AC\CF00\C774\C158 \AE30\B2A5\C744 \D3EC\D568\D558\AC70\B098 \C81C\C678\D558\B3C4\B85D \BE4C\B4DC \C635\C158\C744 \AD6C\C131\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('                                        API\B97C \C0AC\C6A9\D558\C5EC \C560\D50C\B9AC\CF00\C774\C158 \B0B4\C5D0\C11C \C774 \AE30\B2A5\C744 \B178\CD9C\D560 \C218\B3C4 \C788\C2B5\B2C8\B2E4.'),
unistr('                                        \ADF8\B7EC\BA74 \AD8C\D55C\C744 \AC00\C9C4 \C77C\BC18 \C0AC\C6A9\C790\AC00 \C560\D50C\B9AC\CF00\C774\C158 \AE30\B2A5\C744 \C120\D0DD\C801\C73C\B85C \C0AC\C6A9 \B610\B294 \C0AC\C6A9 \C548\D568\C73C\B85C \C124\C815\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
unistr('                                      <p>2. \AE30\B2A5\C744 \AC1C\BC1C\D558\ACE0 \C788\C9C0\B9CC \C544\C9C1 \C644\C131\B418\C9C0 \C54A\C544\C11C \C77C\BC18 \C0AC\C6A9\C790\C5D0\AC8C \B178\CD9C\D558\C9C0 \C54A\C73C\B824\ACE0 \D569\B2C8\B2E4.'),
unistr('									    \BE4C\B4DC \C635\C158\C744 \C0AC\C6A9\D558\BA74 \D14C\C2A4\D2B8 \BC0F \C6B4\C6A9 \D658\ACBD\C5D0\C11C \C791\C131\B418\B294 \ACBD\C6B0\C5D0 \C560\D50C\B9AC\CF00\C774\C158\C5D0\C11C \C774 \AE30\B2A5\C744 \C0AC\C6A9\D558\C9C0 \C54A\B3C4\B85D \C124\C815\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('									    \C774 \BC29\BC95\C740 \C644\C131\B418\C9C0 \C54A\C740 \AE30\B2A5\C744 \D3EC\D568\D558\C9C0 \C54A\ACE0\B3C4 \C560\D50C\B9AC\CF00\C774\C158\C744 \BC30\CE58\D560 \C218 \C788\B2E4\B294 \C774\C810\C774 \C788\C2B5\B2C8\B2E4.</p>'),
unistr('                                      <p>3. \C560\D50C\B9AC\CF00\C774\C158\C5D0 \D544\C694\D558\C9C0 \C54A\B2E4\ACE0 \C0DD\AC01\B418\B294 \AE30\B2A5\C744 \C81C\AC70\D558\B824\ACE0 \D558\C9C0\B9CC \C774\B807\AC8C \D574\B3C4 \C548\C804\D55C\C9C0 \D655\C2E4\D558\C9C0 \C54A\C2B5\B2C8\B2E4.'),
unistr('									    \C774 \ACBD\C6B0 \BE4C\B4DC \C635\C158\C744 \C0AC\C6A9\D558\C5EC \D2B9\C815 \AE30\B2A5\C744 "\C8FC\C11D \CC98\B9AC"\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('									    \BC30\D3EC\D560 \B54C \C81C\AC70\B41C \AE30\B2A5\C774 \D544\C694\D560 \ACBD\C6B0 \D574\B2F9 \AE30\B2A5\C744 \BCF5\C6D0\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('									    \C774 \AE30\B2A5\C774 \D544\C694\D558\C9C0 \C54A\C744 \ACBD\C6B0 \C560\D50C\B9AC\CF00\C774\C158\C5D0\C11C \C548\C804\D558\AC8C \C81C\AC70\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>')))
,p_version_scn=>2565464
);
