,p_name=>'PE.PROPERTY.BUTTON_EXECUTE_VALIDATIONS.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\D398\C774\C9C0\AC00 \C81C\CD9C\B418\ACE0 \C774 \C18D\C131\C774 <strong>\C124\C815</strong>\C73C\B85C \C124\C815\B418\BA74 \D398\C774\C9C0\C5D0 \B300\D574 \C815\C758\B41C \BAA8\B4E0 \AC80\C99D \BC0F \B0B4\C7A5\B41C \AC80\C99D\C774 \C11C\BC84\CE21\C5D0\C11C \C2E4\D589\B429\B2C8\B2E4(\C608: \D544\C218, \C801\D569\D55C \BC88\D638 \B610\B294 \C801\D569\D55C \B0A0\C9DC).'),
unistr('\B610\D55C \C560\D50C\B9AC\CF00\C774\C158\C758 <em>\D638\D658\C131 \BAA8\B4DC</em>\AC00 <strong>5.1</strong> \C774\C0C1\C73C\B85C \C124\C815\B418\B294 \ACBD\C6B0 &PRODUCT_NAME.\C740(\B294) \D074\B77C\C774\C5B8\D2B8\CE21 \AC80\C99D\B3C4 \C218\D589\D569\B2C8\B2E4(\C608: \D56D\BAA9 \D544\C694). \C790\C138\D55C \B0B4\C6A9\C740 \B9B4\B9AC\C2A4 \B178\D2B8\C758 "\D638\D658\C131 \BAA8\B4DC"\B97C \CC38\C870\D558\C2ED\C2DC\C624.'),
unistr('\BAA8\B4E0 \BB38\C81C\AC00 \D574\ACB0\B420 \B54C\AE4C\C9C0 \D398\C774\C9C0\AC00 \C81C\CD9C\B418\C9C0 \C54A\C2B5\B2C8\B2E4.</p>'),
unistr('<p><strong>\D574\C81C</strong>\B85C \C124\C815\D560 \ACBD\C6B0 \C815\C758\B41C \AC80\C99D \B610\B294 \B0B4\C7A5\B41C \AC80\C99D\C774 \C2E4\D589\B418\C9C0 \C54A\C2B5\B2C8\B2E4.'),
unistr('\C774 \C124\C815\ACFC \BCC4\AC1C\B85C \C2E4\D589\D560 \D2B9\C815 \AC80\C99D\C774 \C788\C73C\BA74 \D574\B2F9 \AC80\C99D\C744 \C218\C815\D558\ACE0 \AC80\C99D \C18D\C131 <strong>\D56D\C0C1 \C2E4\D589</strong>\C744 <strong>\C124\C815</strong>\C73C\B85C \C124\C815\D569\B2C8\B2E4.</p>'),
unistr('<p>\C774 \C18D\C131\C740 \AC80\C99D\C744 \B300\BD80\BD84 \C2E4\D589\D558\C9C0 \C54A\C544\C57C \D558\B294 \C0AD\C81C \B610\B294 \CDE8\C18C\C640 \AC19\C740 \B2E8\CD94\C5D0 \D2B9\D788 \C720\C6A9\D569\B2C8\B2E4.'),
unistr('\D56D\BAA9\C774 \B110\C774\AC70\B098 \C798\BABB\B41C \C720\D615\C778 \ACBD\C6B0\C5D0\B294 \C77C\BC18\C801\C73C\B85C \C0AC\C6A9\C790\AC00 \C774\B7EC\D55C \C791\C5C5\C744 \C218\D589\D560 \C218 \C5C6\B3C4\B85D \CC28\B2E8\B418\C5B4\C11C\B294 \C548\B429\B2C8\B2E4.'),
unistr('\D558\C9C0\B9CC \C0AD\C81C\C640 \AC19\C740 \C791\C5C5\C744 \AD8C\D55C\C774 \BD80\C5EC\B41C \C0AC\C6A9\C790\B9CC \C218\D589\D574\C57C \D560 \ACBD\C6B0\C5D0\B294 \D574\B2F9 \AC80\C99D \C18D\C131 <strong>\D56D\C0C1 \C2E4\D589</strong>\C744 <strong>\C124\C815</strong>\C73C\B85C \C124\C815\D558\AC70\B098 \AD8C\D55C\C774 \BD80\C5EC\B41C \C0AC\C6A9\C790\C5D0\AC8C\B9CC \B2E8\CD94\AC00 \D45C\C2DC\B418\B3C4\B85D \B2E8\CD94 \C790\CCB4\C5D0 \C801\D569\D55C \C870\AC74\C774 \C815\C758\B418\C5B4 \C788\B294\C9C0 \D655\C778\D558\B294 \AC83\C774 \C911\C694\D569\B2C8\B2E4.</p>')))
