,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C774 \BCF4\ACE0\C11C\C5D0\C11C \C0AC\C6A9\D560 \D398\C774\C9C0 \B9E4\AE40 \C720\D615\C744 \C120\D0DD\D569\B2C8\B2E4.'),
unistr('\C77C\BC18\C801\C73C\B85C \ACB0\ACFC\C758 \BD80\BD84 \C9D1\D569\B9CC \D604\C7AC \BCF4\ACE0\C11C\C5D0 \D45C\C2DC\B429\B2C8\B2E4.'),
unistr('\D398\C774\C9C0 \B9E4\AE40\C740 \D589 \C218 \BC0F \ACB0\ACFC \C9D1\D569 \B0B4\C5D0\C11C \D604\C7AC \C704\CE58\C5D0 \B300\D55C \C815\BCF4\B97C \C0AC\C6A9\C790\C5D0\AC8C \C81C\ACF5\D569\B2C8\B2E4. \D398\C774\C9C0 \B9E4\AE40\C740 \B610\D55C \B2E4\C74C \B610\B294 \C774\C804 \D398\C774\C9C0\B85C \C774\B3D9\D560 \B54C \C0AC\C6A9\B418\B294 \B9C1\D06C \B610\B294 \B2E8\CD94\C758 \C2A4\D0C0\C77C\B3C4 \C815\C758\D569\B2C8\B2E4.</p>'),
unistr('<p>\D398\C774\C9C0 \B9E4\AE40\C740 \BCF4\ACE0\C11C \C704 \B610\B294 \C544\B798(\B610\B294 \BAA8\B450)\C5D0 \D45C\C2DC\D560 \C218 \C788\C73C\BA70 \C67C\CABD \B610\B294 \C624\B978\CABD\C5D0 \BC30\CE58\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
unistr('<p>\B610\D55C <strong>\D589 \BC94\C704 X-Y(\B2E4\C74C \BC0F \C774\C804 \B9C1\D06C \C0AC\C6A9)</strong>\C640 \AC19\C774 \AC04\C18C\D654\B41C \D398\C774\C9C0 \B9E4\AE40 \C2A4\D0C0\C77C\C744 \C0AC\C6A9\D574\C11C \C131\B2A5\C744 \D5A5\C0C1\C2DC\D0AC \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('"X-Y/Z"\C640 \AC19\C740 \D615\C2DD\C758 \D398\C774\C9C0 \B9E4\AE40 \C720\D615\C744 \C0AC\C6A9\D558\B824\BA74 &PRODUCT_NAME. \C5D4\C9C4\C774 \ACB0\ACFC\B97C \BC18\D658\D558\AE30 \C704\D574 \B450 \AC1C\C758 \C9C8\C758\B97C \C218\D589\D574\C57C \D569\B2C8\B2E4.'),
unistr('\C5EC\AE30\C11C \CCAB\BC88\C9F8 \C9C8\C758\B294 \D45C\C2DC\D560 \D604\C7AC \B808\CF54\B4DC\B97C \AC80\C0C9\D558\ACE0 \B450\BC88\C9F8 \C9C8\C758\B294 \D398\C774\C9C0 \B9E4\AE40 \C81C\C5B4\C5D0 \D45C\C2DC\D560 \CD1D \B808\CF54\B4DC \C218\B97C \AC00\C838\C635\B2C8\B2E4.'),
unistr('\B9E4\C6B0 \D070 \B370\C774\D130 \C9D1\D569\C744 \AE30\C900\C73C\B85C \D558\B294 \BCF4\ACE0\C11C \B610\B294 \BE44\CD5C\C801 \D14C\C774\BE14 \C870\C778 \B610\B294 \D3EC\AD04\C801\C778 \C870\AC74\C774 \BB34\C218\D788 \B9CE\C740 CPU \C0AC\C6A9\B7C9\C774 \B9E4\C6B0 \B192\C740 \C9C8\C758\B97C \D3EC\D568\D558\B294 \BCF4\ACE0\C11C\C758 \ACBD\C6B0\C5D0\B294 \C774\B7EC\D55C \CD94\AC00 \C9C8\C758\B85C \C778\D574 \CC98\B9AC \C2DC\AC04\C774 \B298\C5B4\B098\ACE0 \ACB0\ACFC\C801\C73C\B85C \BCF4\ACE0\C11C\B97C \B80C\B354\B9C1\D558\B294 \B370 \B354 \B9CE\C740 \C2DC\AC04\C774 \AC78\B9B4 \C218 \C788\C2B5\B2C8\B2E4.</p>')))
,p_version_scn=>2565403
);
