,p_name=>'PE.PROPERTY.CONFIRM_ENABLED.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\D655\C778 \D504\B86C\D504\D2B8\B85C \B2E8\CD94\C758 \B3D9\C791\C744 \BCF4\D638\D558\C2ED\C2DC\C624. \B2E8\CD94\B97C \B204\B974\BA74 \D655\C778 \B300\D654\C0C1\C790\AC00 \D45C\C2DC\B429\B2C8\B2E4. \C774\B54C \C0AC\C6A9\C790\B294 \B2E8\CD94 \C791\C5C5\C774 \C218\D589\B418\AE30 \C804\C5D0 \D655\C778\D574\C57C \D569\B2C8\B2E4.</p>'),
unistr('<p>\C774 \AE30\B2A5\C744 \C0AC\C6A9\D558\BA74 \C0AC\C6A9\C790\AC00 \B808\CF54\B4DC \C0AD\C81C\C640 \AC19\C740 \C911\C694\D55C \C791\C5C5\C744 \C2E4\C218\B85C \C218\D589\D558\C9C0 \C54A\B3C4\B85D \D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
unistr('<p>\CC38\ACE0: \B300\D654\C0C1\C790\C758 \D655\C778 \B2E8\CD94\B294 \AE30\BCF8 \B2E8\CD94 \B808\C774\BE14\C5D0\C11C \D574\B2F9 \B808\C774\BE14\C744 \AC00\C838\C635\B2C8\B2E4.</p>')))
,p_version_scn=>2565311
);
