wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(113986704366665058)
,p_name=>'PE.PROPERTY.CONFIRM_MESSAGE.COMPONENT_PROPERTY.BUTTON.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\BA54\C2DC\C9C0 \D655\C778 \B300\D654\C0C1\C790 \B610\B294 \D504\B86C\D504\D2B8\B97C \B514\C790\C778\D560 \B54C \BAA8\B4E0 \C0AC\C6A9\C790\AC00 \D655\C778 \BA54\C2DC\C9C0\B97C \C27D\AC8C \C774\D574\D558\ACE0 \C0C1\D638\C791\C6A9\D560 \C218 \C788\B3C4\B85D \C811\ADFC\C131\C744 \ACE0\B824\D574\C57C \D569\B2C8\B2E4.</p>'),
unistr('<strong>\CD5C\C801\C758 \BC29\BC95:</strong>'),
'<ol>',
unistr('<li><strong>\BA85\D655\D558\ACE0 \C720\C775\D55C \CF58\D150\CE20:</strong>'),
unistr('\D655\C778 \BA54\C2DC\C9C0\B294 \D655\C778\D558\B824\B294 \C791\C5C5\C5D0 \B300\D574 \BA85\D655\D558\ACE0 \AC04\ACB0\D55C \C815\BCF4\B97C \C81C\ACF5\D574\C57C \D569\B2C8\B2E4. \BAA8\B4E0 \C0AC\C6A9\C790\AC00 \C774\D574\D558\AE30 \C26C\C6B4 \AC04\B2E8\D55C \C5B8\C5B4\B97C \C0AC\C6A9\D569\B2C8\B2E4.</li>'),
unistr('<li><strong>\C561\C138\C2A4 \AC00\B2A5\D55C \D615\C2DD \C9C0\C815:</strong>'),
unistr('\C2A4\D06C\B9B0 \B9AC\B354\C640 \AC19\C740 \B2E4\C591\D55C \BCF4\C870 \AE30\C220\C744 \C774\C6A9\D558\C5EC \C0AC\C6A9\C790\AC00 \C561\C138\C2A4\D560 \C218 \C788\B294 \BC29\C2DD\C73C\B85C \D655\C778 \BA54\C2DC\C9C0\C758 \D615\C2DD\C744 \C9C0\C815\D569\B2C8\B2E4. \C758\BBF8 \C788\B294 HTML \C694\C18C\B97C \C0AC\C6A9\D558\ACE0 \B2E8\CD94\C640 \AC19\C774 \D14D\C2A4\D2B8\AC00 \C544\B2CC \C694\C18C\C5D0 \B300\D574 \B300\CCB4 \D14D\C2A4\D2B8\B97C \C81C\ACF5\D569\B2C8\B2E4.</li>'),
unistr('<li><strong>\C77C\AD00\B41C \B514\C790\C778:</strong>'),
unistr('\C560\D50C\B9AC\CF00\C774\C158 \B610\B294 \C6F9 \C0AC\C774\D2B8 \C804\CCB4\C5D0\C11C \BA54\C2DC\C9C0 \D655\C778 \B300\D654\C0C1\C790\C758 \B514\C790\C778\ACFC \BC30\CE58\C5D0 \C77C\AD00\C131\C744 \C720\C9C0\D569\B2C8\B2E4. \C77C\AD00\C131\C740 \C0AC\C6A9\C790\AC00 \D655\C778 \BA54\C2DC\C9C0\C758 \C704\CE58\B97C \200B\200B\C608\CE21\D558\ACE0 \D63C\B780\C744 \C904\C774\B294 \B370 \B3C4\C6C0\C774 \B429\B2C8\B2E4.</li>'),
unistr('<li><strong>\C0AC\C6A9\C790 \C81C\C5B4:</strong>'),
unistr('\D2B9\D788 \C911\C694\D558\AC70\B098 \B418\B3CC\B9B4 \C218 \C5C6\B294 \C791\C5C5\C758 \ACBD\C6B0 \D655\C778 \C804 \C791\C5C5\C744 \AC80\D1A0\D560 \C218 \C788\B294 \C635\C158\C744 \C0AC\C6A9\C790\C5D0\AC8C \C81C\ACF5\D569\B2C8\B2E4. \C774\B97C \D1B5\D574 \C0AC\C6A9\C790\B294 \C815\BCF4\C5D0 \ADFC\AC70\D55C \ACB0\C815\C744 \B0B4\B9B4 \C218 \C788\C73C\BA70 \C758\B3C4\D558\C9C0 \C54A\C740 \C791\C5C5\C774 \BC1C\C0DD\D560 \AC00\B2A5\C131\C774 \C904\C5B4\B4ED\B2C8\B2E4.</li>'),
'</ol>',
unistr('<p>\C774\B7EC\D55C \C811\ADFC\C131 \ACE0\B824\C0AC\D56D\C744 \B530\B974\BA74 \B2A5\B825\C774\B098 \BCF4\C870 \AE30\C220 \C0AC\C6A9\C5D0 \AD00\ACC4\C5C6\C774 \BAA8\B4E0 \C0AC\C6A9\C790\AC00 \BA54\C2DC\C9C0 \D655\C778 \B300\D654\C0C1\C790\B97C \D3EC\AD04\C801\C73C\B85C \C0AC\C6A9 \AC00\B2A5\D558\B3C4\B85D \BCF4\C7A5\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>')))
,p_version_scn=>2565248
);
