,p_name=>'PE.PROPERTY.CREDENTIAL_TYPE.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C5EC\AE30\C5D0 \C778\C99D \C720\D615\C744 \C9C0\C815\D569\B2C8\B2E4. &PRODUCT_NAME.\C740(\B294) \B2E4\C74C \C778\C99D \C720\D615\C744 \C9C0\C6D0\D569\B2C8\B2E4.</p>'),
'<ul>',
unistr('    <li><strong>\AE30\BCF8 \C778\C99D</strong> - Base64 \C778\CF54\B529 \D615\C2DD\C758 \C0AC\C6A9\C790 \C774\B984\ACFC \BE44\BC00\BC88\D638\B97C <strong>\AD8C\D55C \BD80\C5EC</strong> \C694\CCAD \D5E4\B354\B85C \C804\C1A1\D569\B2C8\B2E4.</li>'),
unistr('    <li><strong>OAuth2 \D074\B77C\C774\C5B8\D2B8 \C778\C99D\C11C</strong> - &PRODUCT_NAME.\C774(\AC00) \D1A0\D070 \C11C\BC84 URL\C744 \C0AC\C6A9\D558\C5EC <strong>\C561\C138\C2A4 \D1A0\D070</strong>\C5D0 \B300\D55C \D074\B77C\C774\C5B8\D2B8 ID \BC0F \D074\B77C\C774\C5B8\D2B8 \C554\D638\B97C \AD50\D658\D569\B2C8\B2E4. \C561\C138\C2A4 \D1A0\D070\C740'),
unistr('\C2E4\C81C \C694\CCAD\C744 \C218\D589\D558\B294 \B370 \C0AC\C6A9\B429\B2C8\B2E4. \C561\C138\C2A4 \D1A0\D070\C774 \B9CC\B8CC\B418\BA74 &PRODUCT_NAME.\C740(\B294) \C0C8 \C561\C138\C2A4 \D1A0\D070\C744 \D22C\BA85\D558\AC8C \C694\CCAD\D569\B2C8\B2E4.</li>'),
unistr('    <li><strong>OCI \ACE0\C720 \C778\C99D</strong> - &PRODUCT_NAME.\C774(\AC00) <a rel="noopener noreferrer" href="https://docs.cloud.oracle.com/en-us/iaas/Content/API/Concepts/signingrequests.htm">OCI \C124\BA85\C11C</a>\C5D0 \C124\BA85\B41C \B300\B85C'),
unistr('<em>OCI(Oracle Cloud Infrastructure)</em> REST API\C5D0 \C694\CCAD\C744 \C11C\BA85\D569\B2C8\B2E4.</li>'),
unistr('    <li><strong>HTTP \D5E4\B354</strong> - '),
unistr('\C778\C99D\C11C\AC00 REST \C694\CCAD\C5D0 HTTP \D5E4\B354\B85C \CD94\AC00\B429\B2C8\B2E4. \C778\C99D\C11C\C758 \C774\B984\C740 HTTP \D5E4\B354 \C774\B984\C73C\B85C \C0AC\C6A9\B418\BA70, \C778\C99D\C11C\C758 \C554\D638\B294 HTTP \D5E4\B354 \AC12\C73C\B85C \C0AC\C6A9\B429\B2C8\B2E4. &PRODUCT_NAME.\C774(\AC00) \B514\BC84\ADF8 \B85C\ADF8 \B610\B294 \AE30\D0C0 \B85C\ADF8\C5D0'),
unistr('\D574\B2F9 \C554\D638\B97C \CD94\AC00\D558\C9C0 \C54A\C2B5\B2C8\B2E4.</li>'),
unistr('    <li><strong>URL \C9C8\C758 \BB38\C790\C5F4</strong> - \C778\C99D\C11C\AC00 REST \C694\CCAD\C758 URL\C5D0 <em>\C9C8\C758 \BB38\C790\C5F4</em> \B9E4\AC1C\BCC0\C218(\C608: <strong>?name=value</strong>)\B85C \CD94\AC00\B429\B2C8\B2E4. \C774 \C635\C158\C740 API \D0A4\C5D0\C11C \C720\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr(' &PRODUCT_NAME.\C774(\AC00) \B514\BC84\ADF8 \B85C\ADF8 \B610\B294 \AE30\D0C0 \B85C\ADF8\C5D0 \D574\B2F9 \C554\D638\B97C \CD94\AC00\D558\C9C0 \C54A\C2B5\B2C8\B2E4. \B2E8, \C6F9 \D504\B85D\C2DC \B610\B294 \AE30\D0C0 \C911\AC04 \C11C\BC84\AC00 \B85C\ADF8 \D30C\C77C\C5D0 \D574\B2F9 \C778\C99D\C11C\B97C \AE30\B85D\D560 \C218 \C788\C2B5\B2C8\B2E4.</li>'),
unistr('    <li><strong>\D0A4 \C30D</strong> - \D0A4 \C30D \C778\C99D\C11C\B294 \B370\C774\D130 \C554\D638\D654\B97C \C704\D574 \ACF5\AC1C\C801\C73C\B85C \ACF5\C720\B418\B294 \D37C\BE14\B9AD \D0A4\C640 \B370\C774\D130 \D574\B3C5\C744 \C704\D574 \C548\C804\D558\AC8C \BE44\BC00 \C720\C9C0\B418\B294 \D504\B77C\C774\BE57 \D0A4\B85C \AD6C\C131\B418\C5B4, \B458\C774 \D568\AED8 \C548\C804\D55C \B370\C774\D130 \AD50\D658\C744 \BCF4\C7A5\D569\B2C8\B2E4.</li>'),
'</ul>'))
,p_version_scn=>2565370
);
