wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(115144495471665399)
,p_name=>'PE.PROPERTY.DATABASE_OPERATION.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    \C774 HTTP \C791\C5C5\C5D0 <strong>\B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5</strong>\C744 \C9C0\C815\D569\B2C8\B2E4. &PRODUCT_NAME. \AD6C\C131\C694\C18C\AC00 REST \B370\C774\D130 \C18C\C2A4\C640 \C791\B3D9\D558\B824\BA74 \B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C774 \C911\C694\D569\B2C8\B2E4. &PRODUCT_NAME. \AD6C\C131\C694\C18C\B294 REST \B370\C774\D130 \C18C\C2A4(\C791\C5C5\C774 \C544\B2D8)\C5D0 \C9C0\C815\B418\BBC0\B85C \D544\C694\D55C \B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C744 \AE30\BC18\C73C\B85C HTTP \C791\C5C5\C744 \C870\D68C\D569\B2C8\B2E4.'),
'</p>',
'<ul>',
unistr('    <li>\BCF4\ACE0\C11C, \CC28\D2B8, CSS \B2EC\B825 \BC0F \AE30\D0C0 \B4F1\B4F1\C758 \C2DC\AC01\D654 \AD6C\C131\C694\C18C\B294 \D56D\C0C1 <strong>\D589 \C778\CD9C</strong> \B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C5D0 \C9C0\C815\B41C HTTP \C791\C5C5\C744 \C0AC\C6A9\D569\B2C8\B2E4. <strong>APEX_EXEC.OPEN_WEB_SOURCE_QUERY</strong>\B3C4 \D589 \C778\CD9C \B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C744 \C0AC\C6A9\D569\B2C8\B2E4.</li>'),
unistr('    <li>\D3FC \AD6C\C131\C694\C18C\AC00 \D589\C744 \C0BD\C785, \C5C5\B370\C774\D2B8 \B610\B294 \C0AD\C81C\D560 \B54C \AC01\AC01 <strong>\D589 \C0BD\C785</strong>, <strong>\D589 \C5C5\B370\C774\D2B8</strong> \B610\B294 <strong>\D589 \C0AD\C81C</strong>\C5D0 \C9C0\C815\B41C \C791\C5C5\C744 \C0AC\C6A9\D569\B2C8\B2E4. PL/SQL\C5D0\C11C <strong>APEX_EXEC.OPEN_WEB_SOURCE_DML_CONTEXT</strong>\B294 \D3FC\ACFC \B3D9\C77C\D569\B2C8\B2E4.</li>'),
unistr('    <li>\C190\C2E4\B41C \C5C5\B370\C774\D2B8 \AC10\C9C0 \B610\B294 \D5C8\C6A9\B41C \C791\C5C5 \AC80\C0AC\B97C \C218\D589\D560 \B54C \D3FC \AD6C\C131\C694\C18C\C5D0\C11C <strong>\B2E8\C77C \D589 \C778\CD9C</strong> \B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C774 \C0AC\C6A9\B429\B2C8\B2E4. \ADF8\B9AC\ACE0 \D3FC\C740 \C774 \C791\C5C5\C744 \C0AC\C6A9\D558\C5EC \C2E4\C81C DML \C791\C5C5\C744 \C218\D589\D558\AE30 \C804\C5D0 REST \C11C\BE44\C2A4\C5D0\C11C \D589\C744 \C7AC\C778\CD9C\D569\B2C8\B2E4.</li>'),
unistr('    <li>\B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C5D0 \B9E4\D551\B418\C9C0 \C54A\C740 \C791\C5C5\C740 &PRODUCT_NAME. \AD6C\C131\C694\C18C\C5D0\C11C \C0AC\C6A9\B418\C9C0 \C54A\C2B5\B2C8\B2E4. <strong>APEX_EXEC.EXECUTE_WEB_SOURCE</strong> PL/SQL \D504\B85C\C2DC\C800\B97C \C0AC\C6A9\D558\C5EC PL/SQL \CEE8\D14D\C2A4\D2B8\C5D0\C11C \C2E4\D589\D558\C2ED\C2DC\C624.</li>'),
'</ul>',
'<p>',
'    <br>',
unistr('    \C608\B97C \B4E4\C5B4, &PRODUCT_NAME.\C758 \BCF4\ACE0\C11C \B610\B294 \CC28\D2B8 \AD6C\C131\C694\C18C\C5D0 \D589 \BAA8\C74C\C774 \D544\C694\D569\B2C8\B2E4. REST \B370\C774\D130 \C18C\C2A4\C640'),
unistr('    \C791\B3D9\D560 \B54C &PRODUCT_NAME.\C740(\B294) <strong>\D589 \C778\CD9C</strong> \B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C744 \C870\D68C\D558\ACE0 \C9C0\C815\B41C HTTP \C791\C5C5\C744'),
unistr('    \B7F0\D0C0\C784\C5D0 \C2E4\D589\D569\B2C8\B2E4. \D3FC\C740 \D589 \C0BD\C785, \D589 \C5C5\B370\C774\D2B8 \B610\B294 \D589 \C0AD\C81C \B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C744 \CC3E\C2B5\B2C8\B2E4.'),
'</p>',
'<p>',
unistr('    \AC01 \B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C740 REST \B370\C774\D130 \C18C\C2A4 \B0B4\C5D0\C11C \D55C \BC88\B9CC \C9C0\C815\D560 \C218 \C788\C2B5\B2C8\B2E4. \C2E4\C81C HTTP \C791\C5C5\C5D0\C11C &PRODUCT_NAME. \AD6C\C131\C694\C18C\B97C \CD94\C0C1\D654\D558\BA74 \C0C8 \C791\C5C5\C744 \B2E4\B978 \B3D9\C791\C73C\B85C \C0DD\C131\D558\C5EC \B370\C774\D130\BCA0\C774\C2A4 \C791\C5C5\C5D0 \C9C0\C815\D560 \C218 \C788\C2B5\B2C8\B2E4. \ADF8\B7EC\BA74 \BAA8\B4E0 \AD6C\C131\C694\C18C\B294 \C0C8 HTTP \C791\C5C5\C744 \D22C\BA85\D558\AC8C \C0AC\C6A9\D569\B2C8\B2E4.'),
'</p>',
'<p>',
