,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<p>',
unistr('    \B370\C774\D130\BCA0\C774\C2A4 \C778\C99D\C11C \B0B4\C5D0 \C800\C7A5\B41C \C554\D638\B97C \C0AC\C6A9\D558\B824\BA74 \C5EC\AE30\C5D0 \D574\B2F9 \C774\B984\C744 \C785\B825\D569\B2C8\B2E4.'),
unistr('    \C0AC\C6A9 \AC00\B2A5\D55C \C778\C99D\C11C\B294 <strong>ALL_CREDENTIALS</strong> \B515\C154\B108\B9AC \BDF0\C5D0\C11C'),
unistr('    \AC00\C838\C62C \C218 \C788\C2B5\B2C8\B2E4. <strong>DBMS_CREDENTIAL</strong> \D328\D0A4\C9C0\B97C'),
unistr('    \C0AC\C6A9\D558\C5EC \B370\C774\D130\BCA0\C774\C2A4 \C778\C99D\C11C\B97C \C720\C9C0 \AD00\B9AC\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
'<p>',
unistr('    <em>\B370\C774\D130\BCA0\C774\C2A4 \C778\C99D\C11C\B97C \C0AC\C6A9\D558\BA74 \C218\D589\B418\B294 HTTP \C694\CCAD\C758 \B3D9\C791\ACFC \C6F9 \C778\C99D\C11C\C758 \C791\B3D9 \BC29\C2DD\C774 \BCC0\ACBD\B429\B2C8\B2E4.</em></p>'),
'<ul>',
'    <li>',
unistr('        \B370\C774\D130\BCA0\C774\C2A4 \C778\C99D\C11C\AC00 \C0AC\C6A9\B418\BA74 \BAA8\B4E0 HTTP \C694\CCAD\C774 \B354 \C774\C0C1 APEX \C5D4\C9C4'),
unistr('        \CEE8\D14D\C2A4\D2B8\AC00 \C544\B2CC \C560\D50C\B9AC\CF00\C774\C158\C758 \AD6C\BB38\BD84\C11D \C2A4\D0A4\B9C8 \CEE8\D14D\C2A4\D2B8\C5D0\C11C'),
unistr('        \C218\D589\B429\B2C8\B2E4. \B530\B77C\C11C \C560\D50C\B9AC\CF00\C774\C158\C758 \AD6C\BB38\BD84\C11D \C2A4\D0A4\B9C8\C5D0 PL/SQL '),
unistr('        \B124\D2B8\C6CC\D06C ACL\C774 \BD80\C5EC\B418\C5B4\C57C \D569\B2C8\B2E4. \C790\C138\D55C \B0B4\C6A9\C740'),
unistr('        <strong>DBMS_NETWORK_ACL_ADMIN</strong>\C5D0 \B300\D55C \C124\BA85\C11C\B97C \CC38\C870\D558\C2ED\C2DC\C624.</li>'),
'    <li>',
unistr('        \B370\C774\D130\BCA0\C774\C2A4 \C778\C99D\C11C\B294 \B370\C774\D130\BCA0\C774\C2A4\C5D0\C11C \C644\C804\D788 \C720\C9C0 \AD00\B9AC\B418\BA70 &PRODUCT_NAME.\C740(\B294)'),
unistr('        \C800\C7A5\B41C \C554\D638\C5D0 \B300\D55C \C561\C138\C2A4 \AD8C\D55C\C744 \AC00\C9C0\C9C0 \C54A\C2B5\B2C8\B2E4. \B530\B77C\C11C &PRODUCT_NAME.\C740(\B294)'),
unistr('        <strong>URL\C5D0 \C801\D569</strong> \C18D\C131\C744 \C801\C6A9\D560 \C218 \C5C6\C73C\BBC0\B85C \C774 \C18D\C131\C740 \B370\C774\D130\BCA0\C774\C2A4 \C778\C99D\C11C\AC00 \C0AC\C6A9\B420 \B54C'),
unistr('        \C0AC\C6A9 \C548\D568\C73C\B85C \C124\C815\B429\B2C8\B2E4.</li>'),
'</ul>'))
,p_version_scn=>2565247
