wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(114939752560665338)
,p_name=>'PE.PROPERTY.DB_SESSION_CLEANUP.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<p>\C774 \C18D\C131\C744 \C0AC\C6A9\D558\C5EC \D398\C774\C9C0 \CC98\B9AC\C758 \B9C8\C9C0\B9C9\C5D0 \C2E4\D589\B418\B294 PL/SQL \BE14\B85D\C744 \C785\B825\D569\B2C8\B2E4.'),
unistr('\C774 \C18D\C131\C744 \C0AC\C6A9\D558\BA74 VPD \CEE8\D14D\C2A4\D2B8 \B610\B294 \B370\C774\D130\BCA0\C774\C2A4 \B9C1\D06C\C640 \AC19\C774 \C0AC\C6A9\B41C \B9AC\C18C\C2A4\B97C \D574\C81C\D558\AC70\B098 \C9C0\C6B8 \C218 \C788\C2B5\B2C8\B2E4.'),
'</p>',
unistr('<p>\C608\C81C 1:'),
'<pre>',
'dbms_session.clear_context(''CTX_USER_QRY'');',
'</pre>',
unistr('\C774 \D638\CD9C\C740 \B370\C774\D130\BCA0\C774\C2A4 \C138\C158\C774 \C138\C158 \D480\C5D0 \B2E4\C2DC \C81C\ACF5\B418\AE30 \C804\C5D0 CTX_USER_QRY\B77C\B294 \C560\D50C\B9AC\CF00\C774\C158 \CEE8\D14D\C2A4\D2B8\B97C \C7AC\C124\C815\D558\C5EC'),
unistr('\B098\C911\C5D0 \C7AC\C0AC\C6A9\B420 \B54C \C815\BCF4\AC00 \C720\CD9C\B418\C9C0 \C54A\B3C4\B85D \D569\B2C8\B2E4.'),
'</p>',
unistr('<p>\C608\C81C 2:'),
'<pre>',
'dbms_session.close_database_link(''SALES'');',
'</pre>',
unistr('\C774 \D638\CD9C\C740 "\CD08\AE30\D654 PL/SQL \CF54\B4DC"\B85C \C5F4\B838\C744 \C218 \C788\AC70\B098 \B2E8\C21C\D788 \B9C1\D06C\B97C \D1B5\D574 \B370\C774\D130\B97C \C9C8\C758\D558\C5EC \C554\C2DC\C801\C73C\B85C \C5F4\B838\C744 \C218 \C788\B294 \B370\C774\D130\BCA0\C774\C2A4 \B9C1\D06C SALES\B97C \B2EB\C2B5\B2C8\B2E4.'),
unistr('\C774\B7EC\D55C \BC29\C2DD\C73C\B85C \B9AC\C18C\C2A4\B97C \D574\C81C\D558\ACE0 \B370\C774\D130\BCA0\C774\C2A4 \C138\C158\C744 \C7AC\C0AC\C6A9\D560 \B54C \B9AC\C18C\C2A4 \C720\CD9C\C744 \BC29\C9C0\D569\B2C8\B2E4.'),
'</p>'))
,p_version_scn=>2565371
);
