wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(114939612307665338)
,p_name=>'PE.PROPERTY.DB_SESSION_INIT.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<p>\C774 \C18D\C131\C744 \C0AC\C6A9\D558\BA74 \D604\C7AC "\D398\C774\C9C0 \D45C\C2DC" \B610\B294 "\D398\C774\C9C0 \D5C8\C6A9" \C694\CCAD\ACFC \C5F0\AD00\B41C \B370\C774\D130\BCA0\C774\C2A4 \C138\C158\C5D0 \B300\D55C \CEE8\D14D\C2A4\D2B8\B97C \C124\C815\D558\B294 PL/SQL \BE14\B85D\C744 \C785\B825\D560 \C218 \C788\C2B5\B2C8\B2E4. \C5EC\AE30\C5D0 \C785\B825\D55C \BE14\B85D\C740 <code>APP_USER</code> \AC12\C774 \C124\C815\B41C \C9C1\D6C4 \D398\C774\C9C0 \C694\CCAD \C911\C5D0 \B9E4\C6B0 \C774\B978 \C2DC\C810\C5D0 \C2E4\D589\B429\B2C8\B2E4. \B530\B77C\C11C <code>APP_USER</code>\C758 \AC12(<code>:APP_USER</code> \B610\B294 <code>v(''APP_USER'')</code> \C0AC\C6A9)')
||unistr('\C774 \BE14\B85D \B0B4\C5D0 \C0AC\C6A9\B420 \C218 \C788\C2B5\B2C8\B2E4. \C138\C158 \C0C1\D0DC\C5D0 \C788\B294 \B2E4\B978 \D56D\BAA9\C758 \AC12\C774 \CC38\C870\B420 \C218\B3C4 \C788\C9C0\B9CC \C774\B7EC\D55C \BAA8\B4E0 \D56D\BAA9\C740 \D604\C7AC \D398\C774\C9C0 \C694\CCAD\C774 \C2DC\C791\B418\AE30 \C804\C5D0 \C138\C158 \C0C1\D0DC\C5D0\C11C \C124\C815\B418\C5C8\C5B4\C57C \D569\B2C8\B2E4.'),
unistr('\C608\B97C \B4E4\BA74 \B2E4\C74C\ACFC \AC19\C2B5\B2C8\B2E4.'),
'</p>',
'<pre>',
'dbms_session.set_context(''CTX_USER_QRY'',''USERPRIV'',my_package.my_function(:APP_USER));',
'</pre>',
'',
unistr('<p>\C774 \C608\C5D0\C11C\B294 <code>CTX_USER_QRY</code>\B77C\B294 \C774\B984\C774 \C9C0\C815\B41C \CEE8\D14D\C2A4\D2B8\C5D0 \C788\B294 <code>USERPRIV</code>\C758 \AC12\C744 <code>my_package</code> \D328\D0A4\C9C0\C5D0 \C788\B294 <code>my_function</code> \D568\C218\C5D0\C11C \BC18\D658\D55C \AC12\C73C\B85C \C124\C815\D569\B2C8\B2E4. \D568\C218\C5D0\B294 <code>APP_USER</code>\C758 \D604\C7AC \AC12\C774 \C785\B825 \C778\C218\B85C \C804\B2EC\B429\B2C8\B2E4. \C544\B9C8\B3C4 \C774\B984\C774 \C9C0\C815\B41C \CEE8\D14D\C2A4\D2B8\AC00 VPD \C815\CC45(\C774\BBF8 \C560\D50C\B9AC\CF00\C774\C158\C758 \AD6C\BB38 \BD84\C11D \C2A4\D0A4')
||unistr('\B9C8 \B0B4\C5D0 \C0DD\C131\B428)\C5D0 \C0AC\C6A9\B418\C5B4 \C778\C99D\B41C \C0AC\C6A9\C790\C5D0\AC8C \C801\D569\D55C \C220\C5B4\AC00 \C0DD\C131\B418\B3C4\B85D \D560 \AC83\C785\B2C8\B2E4.</p>'),
'',
unistr('<p>FGAC(Fine-Grained Access Control)\B77C\ACE0\B3C4 \D558\B294 \AC00\C0C1 \D504\B77C\C774\BE57 \B370\C774\D130\BCA0\C774\C2A4\B294 \AC1C\BC1C\C790\AC00 \BCF4\C548 \C815\CC45\C744 \B370\C774\D130\BCA0\C774\C2A4 \D14C\C774\BE14\ACFC \BDF0\C5D0 \C9C0\C815\D558\B294 \B370 \C0AC\C6A9\D560 \C218 \C788\B294 API(Application Programming Interface)\B97C \C81C\ACF5\D558\B294 Oracle \B370\C774\D130\BCA0\C774\C2A4 \AE30\B2A5\C785\B2C8\B2E4. PL/SQL\C744 \C0AC\C6A9\D560 \ACBD\C6B0 \AC1C\BC1C\C790\B294 \B0B4\C7A5 \D504\B85C\C2DC\C800\B85C \BCF4\C548 \C815\CC45\C744 \C0DD\C131\D558\ACE0, RDBMS \D328\D0A4\C9C0\B97C \D638\CD9C\D558\C5EC \D14C\C774\BE14\C774\B098 \BDF0\C5D0 \D504\B85C\C2DC\C800\B97C \BC14\C778\B529\D560 \C218 \C788\C2B5')
||unistr('\B2C8\B2E4. \C774\B7EC\D55C \C815\CC45\C740 \B370\C774\D130\BCA0\C774\C2A4 \B0B4\C5D0 \C800\C7A5\B41C \C560\D50C\B9AC\CF00\C774\C158 \B370\C774\D130\C758 \B0B4\C6A9\C744 \AE30\BC18\C73C\B85C \D558\AC70\B098, Oracle \B370\C774\D130\BCA0\C774\C2A4\C5D0\C11C \C81C\ACF5\D558\B294 \CEE8\D14D\C2A4\D2B8 \BCC0\C218\B97C \AE30\BC18\C73C\B85C \D569\B2C8\B2E4. \C774\C640 \AC19\C740 \BC29\BC95\C73C\B85C VPD\B294 \C561\C138\C2A4 \BCF4\C548 \BC29\C2DD\C744 \C560\D50C\B9AC\CF00\C774\C158\C5D0\C11C \C81C\AC70\D558\ACE0 \D2B9\C815 \C2A4\D0A4\B9C8\C5D0 \B354 \AC00\AE4C\C774 \BC30\CE58\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
'',
unistr('<p>\C5EC\AE30\C5D0 \C785\B825\D55C \CF54\B4DC\B294 VPD/FGAC\C5D0 \D3EC\D568\B420 \D544\C694\AC00 \C5C6\C73C\BA70 \BCF4\C548\ACFC\B3C4 \C804\D600 \AD00\B828\B418\C9C0 \C54A\C744 \C218 \C788\C2B5\B2C8\B2E4. \D398\C774\C9C0 \C694\CCAD\C5D0\C11C \CD5C\CD08 \C9C0\C810\C5D0 \C2E4\D589\D574\C57C \D558\B294 \BAA8\B4E0 \CF54\B4DC\B294 \C5EC\AE30\C5D0 \BC30\CE58\D560 \C218 \C788\C2B5\B2C8\B2E4. \C608\B97C \B4E4\C5B4, \B2E4\C74C \CF54\B4DC\C5D0\C11C\B294 \BAA8\B4E0 \D398\C774\C9C0 \C694\CCAD\C5D0\C11C \B370\C774\D130\BCA0\C774\C2A4 \C138\C158 \C2DC\AC04\B300\B97C \C124\C815\D569\B2C8\B2E4.</p>'),
'',
'<pre>',
'BEGIN',
'   EXECUTE IMMEDIATE ''alter session set time_zone = ''''Australia/Sydney'''' '';',
'END;',
'</pre>'))
,p_version_scn=>2565371
);
