wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(114571652357665231)
,p_name=>'PE.PROPERTY.ERROR_HANDLING_FUNCTION.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C560\D50C\B9AC\CF00\C774\C158 \B0B4\C5D0 \C624\B958\AC00 \BC1C\C0DD\D560 \B54C \D638\CD9C\B418\B294 PL/SQL \D568\C218\C758 \C774\B984\C744 \C785\B825\D569\B2C8\B2E4.'),
unistr('\C774 \D568\C218\B97C \C0AC\C6A9\D574\C11C Oracle \B370\C774\D130\BCA0\C774\C2A4\C5D0\C11C \B098\C624\B294 \CF54\B4DC\B97C \D3EC\D568\D574\C11C \C5EC\B7EC \AC00\C9C0 \C624\B958 \CF54\B4DC\C5D0 \B300\D55C \C791\C5C5\C744 \C218\D589\D558\ACE0 \D544\C694\C5D0 \B530\B77C \C815\C758\D55C \C0AC\C6A9\C790\C815\C758 \D14C\C774\BE14\C5D0 \C774\B7EC\D55C \C624\B958\B97C \AE30\B85D\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('\C774 \D568\C218\B294 \C624\B958 \BA54\C2DC\C9C0\B97C \C218\C815\D558\ACE0 \C704\CE58\B97C \D45C\C2DC\D558\B294 \B17C\B9AC\B97C \D3EC\D568\D558\C5EC Oracle \B370\C774\D130\BCA0\C774\C2A4 \C624\B958\B97C \C0AC\C6A9\C790\C5D0\AC8C \D3B8\B9AC\D55C \BA54\C2DC\C9C0\B85C \BCC0\D658\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('\C608\B97C \B4E4\C5B4, <code>DEMO_CUSTOMERS</code>\C5D0 \B300\D55C \ACE0\C720 \D0A4 \C704\BC18\C744 \CEA1\CC98\D558\ACE0 <code>ORA-00001</code> \BA54\C2DC\C9C0\B97C Customer Name must be unique\C640 \AC19\C740 \D14D\C2A4\D2B8\B85C \BC14\AFC0 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('\AC24\B7EC\B9AC\C5D0\C11C <strong>\C124\BB38</strong> \C2DC\C791 \C571\C744 \C124\CE58\D558\BA74 <code>apex_error_handling</code> \D568\C218\AC00 \D3EC\D568\B41C <code>EBA_QPOLL_FW</code> \D328\D0A4\C9C0\AC00 \C0DD\C131\B429\B2C8\B2E4.'),
unistr('\C774 \C624\B958 \CC98\B9AC \D568\C218\B294 \ACE0\C720 \D568\C218\B97C \C815\C758\D558\AE30 \C704\D55C \AE30\C900\C73C\B85C \C27D\AC8C \C0AC\C6A9\D560 \C218 \C788\B3C4\B85D \C790\C138\D55C \C124\BA85\C744 \D3EC\D568\D569\B2C8\B2E4.</p>'),
unistr('<p>\C785\B825\D55C \D568\C218 \C774\B984\C740 \B370\C774\D130\BCA0\C774\C2A4\C5D0\C11C \D328\D0A4\C9C0 \D568\C218 \B610\B294 \B3C5\B9BD\D615 \D568\C218\B97C \CC38\C870\D560 \C218 \C788\C2B5\B2C8\B2E4. \C608:'),
'<pre>',
'log_apex_error',
'</pre>',
'</p>',
unistr('<p>\B370\C774\D130\BCA0\C774\C2A4 PL/SQL \D328\D0A4\C9C0 \B610\B294 \B3C5\B9BD\D615 \D568\C218\B97C \CC38\C870\D560 \ACBD\C6B0 <code>#OWNER#</code> \B300\CCB4 \BB38\C790\C5F4\C744 \C0AC\C6A9\D558\C5EC \D604\C7AC \C560\D50C\B9AC\CF00\C774\C158\C758 \AD6C\BB38\BD84\C11D \C2A4\D0A4\B9C8\B97C \CC38\C870\D560 \C218 \C788\C2B5\B2C8\B2E4. \C608:'),
'<pre>#OWNER#.log_apex_error</pre>',
'</p>',
unistr('<p>\C624\B958 \CC98\B9AC \D568\C218\AC00 \D398\C774\C9C0\C5D0 \C9C0\C815\B418\C5C8\C73C\BA74 \D574\B2F9 \D398\C774\C9C0\C5D0 \B300\D574 \C774 \C560\D50C\B9AC\CF00\C774\C158 \B808\BCA8 \C124\C815 \B300\C2E0 \C624\B958 \CC98\B9AC \D568\C218\AC00 \C0AC\C6A9\B429\B2C8\B2E4.</p>'),
unistr('<p>\C624\B958 \CC98\B9AC \D568\C218\B294 \B2E4\C74C \C778\D130\D398\C774\C2A4\B97C \AD6C\D604\D574\C57C \D569\B2C8\B2E4.'),
'<pre>',
'function &lt;name of function> (',
'    p_error in apex_error.t_error )',
'    return apex_error.t_error_result',
'</pre>',
'</p>',
unistr('<p><code>apex_error</code> \D328\D0A4\C9C0\C5D0 \B300\D55C \C124\BA85\C740 API \CC38\C870 \C124\BA85\C11C\B97C \CC38\C870\D558\C2ED\C2DC\C624.</p>')))
,p_version_scn=>2565330
);
