,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C774 \D504\B85C\C138\C2A4\C5D0 \B300\D55C \C624\B958 \BA54\C2DC\C9C0\B97C \C785\B825\D569\B2C8\B2E4.'),
unistr('\C774 \BA54\C2DC\C9C0\B294 \CC98\B9AC\B418\C9C0 \C54A\C740 \C608\C678\C0AC\D56D\C774 \BC1C\C0DD\D560 \B54C \D45C\C2DC\B429\B2C8\B2E4. \C624\B958 \CC98\B9AC\AC00 \C815\C9C0\B41C \D6C4\C5D0\B294 \B864\BC31\C774 \C2E4\D589\B418\ACE0 \C624\B958 \BA54\C2DC\C9C0\AC00 \D45C\C2DC\B429\B2C8\B2E4.</p>'),
unistr('<p>\CC38\ACE0: SQL \C624\B958 \BA54\C2DC\C9C0 sqlerrm\C740 <strong>\C624\B958 \BC1C\C0DD \C2DC \D398\C774\C9C0</strong>\AC00 \C624\B958 \D45C\C2DC \C704\CE58\B85C \C815\C758\B418\C5C8\ACE0 \C624\B958 \D14D\C2A4\D2B8\C5D0 <code>#SQLERRM#</code>\C744 \CD94\AC00\D560 \D544\C694\AC00 \C5C6\B294 \ACBD\C6B0\C5D0 \AE30\BCF8\C801\C73C\B85C \D45C\C2DC\B429\B2C8\B2E4.</p>'),
unistr('<p>\C624\B958 \BA54\C2DC\C9C0\B294 \B2E4\C74C\ACFC \AC19\C740 \B300\CCB4 \BB38\C790\C5F4\C744 \D3EC\D568\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
'<dl>',
'  <dt><code>#SQLERRM_TEXT#</code></dt>',
'  <dd>Text of error message without the error number.</dd>',
'  <dt><code>#SQLERRM#</code></dt>',
'  <dd>Complete error message.</dd>',
'</dl>'))
,p_version_scn=>2565400
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(113987622343665058)
,p_name=>'PE.PROPERTY.ERROR_MESSAGE.COMPONENT_PROPERTY.VALIDATION.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C561\C138\C2A4 \AC00\B2A5\D55C \C624\B958 \C81C\C548\C740 \BCF4\B2E4 \D3EC\AD04\C801\C778 \C0AC\C6A9\C790 \D658\ACBD\C744 \C870\C131\D558\C5EC \B2E4\C591\D55C \B2A5\B825\C744 \AC00\C9C4 \C0AC\C6A9\C790\AC00 \C785\B825 \C624\B958\B97C \D6A8\C728\C801\C73C\B85C \C218\C815\D560 \C218 \C788\B3C4\B85D \C9C0\C6D0\D569\B2C8\B2E4.</p>'),
unistr('<strong>\CD5C\C801\C758 \BC29\BC95:</strong>'),
'<ol>',
unistr('<li><strong>\BA85\D655\D558\ACE0 \C124\BA85 \D3EC\D568:</strong> \C624\B958 \BA54\C2DC\C9C0\B294 \C0AC\C6A9\C790\C5D0\AC8C \BC1C\C0DD\D55C \BB38\C81C\B97C \AC04\ACB0\D558\ACE0 \C774\D574\D558\AE30 \C26C\C6B4 \BC29\C2DD\C73C\B85C \BA85\D655\D558\AC8C \C124\BA85\D574\C57C \D569\B2C8\B2E4. \C0AC\C6A9\C790\C5D0\AC8C \D63C\B780\C744 \C904 \C218 \C788\B294 \AE30\C220 \C804\BB38 \C6A9\C5B4\B098 \BAA8\D638\D55C \C5B8\C5B4\B97C \C0AC\C6A9\D558\C9C0 \B9C8\C2ED\C2DC\C624.</li>'),
unistr('<li><strong>\D574\ACB0 \BC29\BC95 \C81C\ACF5:</strong> \C0AC\C6A9\C790\AC00 \C624\B958\B97C \D574\ACB0\D560 \C218 \C788\B294 \BC29\BC95\C5D0 \B300\D55C \BA85\D655\D55C \C9C0\CE68 \B610\B294 \C81C\C548\C744 \C81C\ACF5\D569\B2C8\B2E4.</li>'),
unistr('<li><strong>\C624\B958 \C2DD\BCC4:</strong> \C624\B958\B97C \D2B8\B9AC\AC70\D55C \D544\B4DC \B610\B294 \C785\B825 \C694\C18C\B97C \BA85\D655\D558\AC8C \C2DD\BCC4\D569\B2C8\B2E4. \C0AC\C6A9\C790\AC00 \D3FC \B610\B294 \C560\D50C\B9AC\CF00\C774\C158\C758 \C5B4\B290 \BD80\BD84\C5D0 \C8FC\C758\AC00 \D544\C694\D55C\C9C0 \C774\D574\D560 \C218 \C788\B3C4\B85D \CDA9\BD84\D55C \CEE8\D14D\C2A4\D2B8\B97C \C81C\ACF5\D569\B2C8\B2E4.</li>'),
unistr('<li><strong>\C77C\AD00\C131:</strong> \C560\D50C\B9AC\CF00\C774\C158 \B610\B294 \C6F9 \C0AC\C774\D2B8 \C804\CCB4\C5D0\C11C \C624\B958 \BA54\C2DC\C9C0\C758 \D615\C2DD\ACFC \C2A4\D0C0\C77C\C5D0 \C77C\AD00\C131\C744 \C720\C9C0\D569\B2C8\B2E4. \C77C\AD00\B41C \C624\B958 \BA54\C2DC\C9C0\B294 \C0AC\C6A9\C790\AC00 \C778\D130\D398\C774\C2A4\B97C \BCF4\B2E4 \D6A8\ACFC\C801\C73C\B85C \C774\D574\D558\ACE0 \D0D0\C0C9\D558\B294 \B370 \B3C4\C6C0\C774 \B429\B2C8\B2E4.</li>'),
'</ol>',
unistr('<strong>\C608:</strong>'),
'<ul>',
unistr('<li>\C624\B958: "\C804\C790\BA54\C77C \C8FC\C18C\AC00 \BD80\C801\D569\D569\B2C8\B2E4. \C801\D569\D55C \C804\C790\BA54\C77C \D615\C2DD(\C608: example@example.com)\C744 \C785\B825\D558\C2ED\C2DC\C624."</li>'),
unistr('<li>\C624\B958: "\C790\AE08\C774 \BD80\C871\D569\B2C8\B2E4. \AC70\B798\B97C \C644\B8CC\D558\B824\BA74 \ACC4\C88C\C5D0 \C790\AE08\C744 \CD94\AC00\D558\C2ED\C2DC\C624."</li>'),
'</ul>'))
,p_version_scn=>2565248
);
