,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\AD8C\D55C \BD80\C5EC \CCB4\ACC4\B294 \C138\C158\C5D0\C11C \CC98\C74C \C0AC\C6A9\D560 \B54C \D3C9\AC00\B429\B2C8\B2E4.'),
unistr('\C81C\ACF5\B41C \AD8C\D55C \BD80\C5EC\B97C \C774\D6C4\C5D0 \C0AC\C6A9\D560 \B54C \BA54\BAA8\B9AC\C5D0\C11C \ACB0\ACFC\B97C \AC00\C838\C624\AC70\B098 \AD8C\D55C \BD80\C5EC \CCB4\ACC4\B97C \B2E4\C2DC \D3C9\AC00\D560\C9C0 \C5EC\BD80\B97C \D655\C778\D558\AE30 \C704\D574 \C801\D569\D55C \D3C9\AC00 \C9C0\C810\C744 \C120\D0DD\D569\B2C8\B2E4.</p>'),
'#LOV_VALUES#',
unistr('<p>\AE30\BCF8\AC12 <em>\C138\C158\B2F9 \D55C \BC88\C529</em>\C774 \AC00\C7A5 \D6A8\C728\C801\C785\B2C8\B2E4.'),
