,p_name=>'PE.PROPERTY.FIELD_TEMPLATE.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C774 \D56D\BAA9 \B808\C774\BE14\C758 \BAA8\C591\ACFC \B808\C774\C544\C6C3\C744 \C815\C758\D560 \B808\C774\BE14 \D15C\D50C\B9AC\D2B8\B97C \C120\D0DD\D569\B2C8\B2E4.</p>'),
unistr('        <p>\B808\C774\BE14 \D15C\D50C\B9AC\D2B8\B294 \C560\D50C\B9AC\CF00\C774\C158 \D14C\B9C8\C5D0\C11C \C815\C758\B429\B2C8\B2E4.'),
unistr('        \D56D\BAA9\C774 \C0DD\C131\B418\BA74 \D15C\D50C\B9AC\D2B8\B294 \D604\C7AC \D14C\B9C8\C5D0 \C815\C758\B41C \AE30\BCF8 \D56D\BAA9 \D15C\D50C\B9AC\D2B8\B85C \C790\B3D9\C73C\B85C \C124\C815\B429\B2C8\B2E4.</p>'),
unistr('        <p>\B300\BD80\BD84\C758 \D14C\B9C8\C5D0\B294 \D544\C218, \C120\D0DD\C0AC\D56D, \C228\AE40 \B808\C774\BE14\C744 \D45C\C2DC\D558\AE30 \C704\D55C \B808\C774\BE14 \D15C\D50C\B9AC\D2B8\AC00 \D3EC\D568\B418\C5B4 \C788\C2B5\B2C8\B2E4.<br>'),
unistr('        \BC94\C6A9 \D14C\B9C8\B294 \B2E4\C74C\ACFC \AC19\C740 \B808\C774\BE14 \D15C\D50C\B9AC\D2B8\B97C \C81C\ACF5\D569\B2C8\B2E4.'),
'          <dl>',
unistr('            <dt>\C228\AE40</dt>'),
unistr('              <dd>\B808\C774\BE14\C774 \D654\BA74\C5D0 \D45C\C2DC\B418\C9C0 \C54A\C544\C57C \D560 \ACBD\C6B0 \C774 \D15C\D50C\B9AC\D2B8\B97C \C0AC\C6A9\D569\B2C8\B2E4. \BCF4\C870 \ACF5\D559\C744 \C0AC\C6A9\D558\C5EC \B808\C774\BE14\C744 \C77D\C744 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('              \CCB4\D06C\BC15\C2A4 \B4A4\C5D0 \B808\C774\BE14\C774 \D45C\C2DC\B418\C5B4\C57C \D558\BBC0\B85C \CCB4\D06C\BC15\C2A4 \D56D\BAA9\C5D0\B294 \C228\AE40\C774 \BB34\C2DC\B429\B2C8\B2E4.</dd>'),
unistr('            <dt>\C120\D0DD\C0AC\D56D</dt>'),
unistr('              <dd>\C120\D0DD\C0AC\D56D\C778 \D3FC \D56D\BAA9\C5D0 \B300\D574 \C774 \D15C\D50C\B9AC\D2B8\B97C \C0AC\C6A9\D569\B2C8\B2E4. \B808\C774\BE14\C774 \D56D\BAA9\C758 \CE21\BA74\C5D0 \D45C\C2DC\B429\B2C8\B2E4.</dd>'),
unistr('            <dt>\C120\D0DD\C0AC\D56D - \C704</dt>'),
unistr('              <dd>\C120\D0DD\C0AC\D56D\C778 \D3FC \D56D\BAA9\C5D0 \B300\D574 \C774 \D15C\D50C\B9AC\D2B8\B97C \C0AC\C6A9\D569\B2C8\B2E4. \B808\C774\BE14\C774 \D56D\BAA9 \C704\C5D0 \D45C\C2DC\B429\B2C8\B2E4.</dd>'),
unistr('            <dt>\C120\D0DD\C0AC\D56D - \BD80\B3D9</dt>'),
