unistr('            <dt>\D544\C218</dt>'),
unistr('              <dd>\C774 \B808\C774\BE14 \D15C\D50C\B9AC\D2B8\B294 \B808\C774\BE14 \C606\C5D0 \BE68\AC04\C0C9 \BCC4\D45C\AC00 \D45C\C2DC\B418\BA70 \C0AC\C6A9\C790 \C785\B825\C774 \D544\C694\D55C \D3FC \D56D\BAA9\C5D0 \C0AC\C6A9\B429\B2C8\B2E4. \B808\C774\BE14\C774 \D56D\BAA9\C758 \CE21\BA74\C5D0 \D45C\C2DC\B429\B2C8\B2E4.</dd>'),
unistr('            <dt>\D544\C218 - \C704</dt>'),
