,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C544\C774\CF58 \C124\BA85\C740 \D3EC\CEE4\C2A4\B97C \BC1B\AC70\B098 \CEE4\C11C\B97C \C704\B85C \AC00\C838\AC08 \B54C \D45C\C2DC\B418\B294 \C544\C774\CF58\C5D0 \B300\D55C \CEE8\D14D\C2A4\D2B8 \C815\BCF4\B97C \C81C\ACF5\D558\C5EC \C911\C694\D55C \C811\ADFC\C131 \AE30\B2A5\C73C\B85C \C0AC\C6A9\B429\B2C8\B2E4. \C774 \AE30\B2A5\C740 \C778\D130\D398\C774\C2A4\C5D0 \B300\D55C \C0AC\C6A9\C790\C758 \C774\D574\C640 \C0C1\D638\C791\C6A9\C744 \D5A5\C0C1\C2DC\D0B5\B2C8\B2E4.</p>'),
unistr('<strong>\CD5C\C801\C758 \BC29\BC95:</strong>'),
'<ol>',
unistr('<li><strong>\BA85\D655\D558\ACE0 \AC04\ACB0\D558\AC8C:</strong> \C544\C774\CF58 \C124\BA85\C740 \BA85\D655\D558\ACE0 \AC04\ACB0\D574\C57C \D558\BA70 \C0AC\C6A9\C790\C5D0\AC8C \C544\C774\CF58\C758 \AE30\B2A5\C774\B098 \C6A9\B3C4\C5D0 \B300\D574 \AC04\B2E8\D558\BA74\C11C\B3C4 \C720\C775\D55C \C774\D574\B97C \C81C\ACF5\D574\C57C \D569\B2C8\B2E4.</li>'),
unistr('<li><strong>\C124\BA85\C774 \D3EC\D568\B41C \C5B8\C5B4:</strong> \C544\C774\CF58\ACFC \C5F0\AD00\B41C \C758\BBF8\B098 \B3D9\C791\C744 \C815\D655\D558\AC8C \C804\B2EC\D558\B294 \C124\BA85\C774 \D3EC\D568\B41C \C5B8\C5B4\B97C \C0AC\C6A9\D569\B2C8\B2E4. \C0AC\C6A9\C790\C5D0\AC8C \D63C\B780\C744 \C904 \C218 \C788\B294 \C560\B9E4\D558\AC70\B098 \BAA8\D638\D55C \C124\BA85\C740 \D53C\D558\C2ED\C2DC\C624.</li>'),
unistr('<li><strong>\B300\CCB4 \D14D\C2A4\D2B8 \D544\C694\C131 \ACB0\C815:</strong>'),
unistr('\C544\C774\CF58\C774 \C5C6\C73C\BA74 \D398\C774\C9C0 \C774\D574\C5D0 \C601\D5A5\C744 \BBF8\CE58\B294\C9C0 \D3C9\AC00\D569\B2C8\B2E4.'),
unistr('\C544\C774\CF58\C774 \C5C6\C73C\BA74 \D398\C774\C9C0\C758 \C758\BBF8\AC00 \C0C1\C2E4\B418\B294 \ACBD\C6B0 \B300\CCB4 \D14D\C2A4\D2B8\B97C \CD94\AC00\D569\B2C8\B2E4.</li>'),
'</ol>'))
,p_version_scn=>2565249
);
