,p_name=>'PE.PROPERTY.INIT_POSITION_ZOOM_SOURCE_SQL.EXAMPLES'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\CD08\AE30 \B9F5 \C704\CE58 \BC0F \D655\B300/\CD95\C18C \B808\BCA8\C744 \ACB0\C815\D558\AE30 \C704\D574 NUMBER \C5F4\C744 \BC18\D658\D558\B294 \C9C8\C758:</p>'),
'<pre>',
'select -133.5 longitude,',
'         35.2 latitude,',
'            3 zoom',
'  from sys.dual',
'</pre>',
unistr('<p>\CD08\AE30 \B9F5 \C704\CE58\B97C \ACB0\C815\D558\AE30 \C704\D574 SDO_GEOMETRY \C5F4\C744 \BC18\D658\D558\ACE0 \D655\B300/\CD95\C18C \B808\BCA8\C744 \C704\D574 NUMBER \C5F4\C744 \BC18\D658\D558\B294 \C9C8\C758\C785\B2C8\B2E4.</p>'),
'<pre>',
'select sdo_geometry( 2001,                                 -- 2 dimensional point',
'                     4326,                                 -- longitude/latitude (WGS84)',
'                     sdo_point_type( -133.5, 35.2, null ), -- concrete coordinates',
'                     null,                                 -- not used for points',
'                     null                                  -- not used for points',
'       )                   as geometry,',
'       3                   as zoom',
'  from sys.dual',
'</pre>'))
,p_version_scn=>2565438
);
