wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(114572203134665231)
,p_name=>'PE.PROPERTY.INLINE_CSS.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C774 \D398\C774\C9C0\C758 CSS \CF54\B4DC\B97C \C785\B825\D569\B2C8\B2E4. \C5EC\AE30 \C785\B825\B41C \BAA8\B4E0 CSS\B294 \C774 \D398\C774\C9C0\C5D0\B9CC \C801\C6A9\B418\BA70 \B2E4\B978 \D398\C774\C9C0\C5D0 \C601\D5A5\C744 \B07C\CE58\C9C0 \C54A\C2B5\B2C8\B2E4. \C785\B825\B41C CSS \CF54\B4DC\B294 \D398\C774\C9C0 \D15C\D50C\B9AC\D2B8\C758 #PAGE_CSS# \B300\CCB4 \BB38\C790\C5F4\C744 \BC14\AFC9\B2C8\B2E4.</p>'),
unistr('<p>\C5EC\B7EC \D398\C774\C9C0\C5D0 \B3D9\C77C\D55C CSS\AC00 \D544\C694\D55C \ACBD\C6B0 \CF54\B4DC\B97C \C678\BD80 \D30C\C77C\C5D0 \B123\B294 \AC83\C774 \AC00\C7A5 \C88B\C2B5\B2C8\B2E4. \C774\B294 \C911\BCF5\C744 \D53C\D558\ACE0 \C815\C801 \D30C\C77C\C758 \BE0C\B77C\C6B0\C800 \CE90\C2F1\C744 \D65C\C6A9\D558\B294 \B370 \B3C4\C6C0\C774 \B429\B2C8\B2E4. [\ACF5\C720 \AD6C\C131\C694\C18C], [\C0AC\C6A9\C790 \C778\D130\D398\C774\C2A4 \C18D\C131], [CSS], [\D30C\C77C URL] \C544\B798\C758 \C560\D50C\B9AC\CF00\C774\C158 \B808\BCA8\C5D0\C11C \C678\BD80 \D30C\C77C\C744 \CC38\C870\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
unistr('<p>\C5F4\AC70\B098 \B2EB\B294 <code>style</code> \D0DC\ADF8\B97C \D3EC\D568\D560 \D544\C694\AC00 \C5C6\C2B5\B2C8\B2E4. CSS \CF54\B4DC\B97C \CD94\AC00\D558\AE30\B9CC \D558\BA74 \B429\B2C8\B2E4.</p>')))
,p_version_scn=>2565330
);
