,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\B370\C774\D130 \C2DC\AC01\D654\C758 \D3EC\AD04\C131\C774 \BCF4\C7A5\B418\B3C4\B85D \C2E0\C911\D55C \C0C9\C0C1 \C120\D0DD\ACFC WCAG \D45C\C900 \C900\C218\B97C \D1B5\D574 \CC28\D2B8 \C811\ADFC\C131\C744 \D5A5\C0C1\C2DC\D0A4\B294 \AC83\C774 \C911\C694\D569\B2C8\B2E4.</p>'),
unistr('<strong>\CD5C\C801\C758 \BC29\BC95:</strong>'),
'<ol>',
unistr('<li><strong>\AD75\ACE0 \C120\BA85\D55C \C0C9\C0C1 \C0AC\C6A9:</strong> \CC28\D2B8 \B0B4\C758 \D14D\C2A4\D2B8\C640 \ADF8\B798\D53D \C694\C18C\B97C \C27D\AC8C \AD6C\BD84\D560 \C218 \C788\B3C4\B85D \AD75\ACE0 \C120\BA85\D55C \C0C9\C0C1\C744 \C120\D0DD\D569\B2C8\B2E4. \ADF8\B7EC\BA74 \C2DC\AC01 \C7A5\C560\AC00 \C788\B294 \C0AC\C6A9\C790\B97C \BE44\B86F\D55C \BAA8\B4E0 \C0AC\C6A9\C790\C758 \AC00\B3C5\C131\ACFC \C774\D574\B825\C774 \D5A5\C0C1\B429\B2C8\B2E4.</li>'),
unistr('<li><strong>\C0C9\C0C1 \B300\BE44 \BE44\C728 \AC80\C0AC:</strong> \B300\BE44 \AC80\C0AC \D234\C744 \D65C\C6A9\D558\C5EC \C804\ACBD\C0C9\ACFC \BC30\ACBD\C0C9 \AC04\C758 \C0C9\C0C1 \B300\BE44 \BE44\C728\C744 \D3C9\AC00\D569\B2C8\B2E4. \C2DC\AC01 \C7A5\C560 \B808\BCA8\C774 \B2E4\C591\D55C \AC1C\AC1C\C778\C758 \AC00\B3C5\C131\C774 \BCF4\C7A5\B418\B3C4\B85D \CD5C\C18C\D55C 4.5:1 \BE44\C728\C744 \BAA9\D45C\B85C \D569\B2C8\B2E4.</li>'),
'</ol>'))
,p_version_scn=>2565249
);
