,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C9C0\C815\B41C \C18D\C131\C5D0 \B300\D574 \AE00\AF34\C744 \D45C\C2DC\D558\B294 \B370 \C0AC\C6A9\B418\B294 \C0C9\C0C1\C744 \C785\B825\D569\B2C8\B2E4.</p>'),
unistr('<p>\C0C9\C0C1\C740 16\C9C4\C218(hex) \D45C\AE30\BC95, RGB \C0C9\C0C1 \CF54\B4DC \B610\B294 HTML \C0C9\C0C1 \C774\B984\C744 \C0AC\C6A9\D574\C11C \C9C0\C815\B429\B2C8\B2E4. 16\C9C4\C218 \D45C\AE30\BC95\C740 #xxyyzz(# \B2E4\C74C\C5D0 \C138 \AC1C\C758 \B450 \C790\B9BF\C218 16\C9C4\C218 \C22B\C790\AC00 \C634)\B85C \C815\C758\B429\B2C8\B2E4. \C5EC\AE30\C11C xx, yy \BC0F zz\B294 \AC01\AC01 \BE68\AC04\C0C9, \B179\C0C9 \BC0F \D30C\B780\C0C9\C758 2\C790\B85C \B41C 16\C9C4\C218 \AC12\C785\B2C8\B2E4.'),
unistr('RGB \CF54\B4DC\B294 RGB(xxx,xxx,xxx)\B85C \C815\C758\B429\B2C8\B2E4. \C5EC\AE30\C11C xxx\B294 0~255 \C0AC\C774\C758 \C22B\C790\C774\BA70, \AC01\AC01 \BE68\AC04\C0C9, \B179\C0C9 \BC0F \D30C\B780\C0C9\C758 \B2E8\C77C 8\BE44\D2B8 \BC14\C774\D2B8 \AC12\C744 \B098\D0C0\B0C5\B2C8\B2E4.</p>'),
unistr('<p>\C0AC\C6A9\D558\B824\B294 \C0C9\C0C1\C5D0 \D574\B2F9\D558\B294 16\C9C4\C218 \CF54\B4DC \B610\B294 RGB \CF54\B4DC\B97C \CC3E\C544\BCF4\B824\BA74 \C778\D130\B137\C5D0\C11C ''HTML \C0C9\C0C1 \CF54\B4DC''\B97C \AC80\C0C9\D574\BCF4\C2ED\C2DC\C624.</p>')))
,p_version_scn=>2565329
);
