,p_name=>'PE.PROPERTY.LANDMARK_LABEL.COMPONENT_PROPERTY.REGION.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C0AC\C6A9\C790 \ACBD\D5D8\C744 \C9C4\C815\C73C\B85C \D5A5\C0C1\C2DC\D0A4\B294 \C88B\C740 \B808\C774\BE14\C744 \C81C\ACF5\D558\B294 \AC83\C774 \C911\C694\D569\B2C8\B2E4. \C88B\C740 \B808\C774\BE14\C740 \B2E4\C74C\ACFC \AC19\C774 \C815\C758\B429\B2C8\B2E4.'),
'<ul>',
unistr('<li>\D398\C774\C9C0\C5D0\C11C \ACE0\C720\D558\ACE0 \B108\BB34 \AE38\C9C0 \C54A\C2B5\B2C8\B2E4(\AC00\AE09\C801 3\B2E8\C5B4 \C774\D558).</li>'),
unistr('<li>\C601\C5ED \CF58\D150\CE20\C758 \BAA9\C801\C744 \C815\D655\D788 \C124\BA85\D569\B2C8\B2E4(\C608: ''\C9C1\C6D0 \D3B8\C9D1'' \B610\B294 ''\C720\C6A9\D55C \B9C1\D06C'').</li>'),
unistr('<li>\B808\C774\BE14\C5D0 \B79C\B4DC\B9C8\D06C \B864\C744 \C0AC\C6A9\D558\C9C0 \B9C8\C2ED\C2DC\C624. \C608\B97C \B4E4\C5B4, \C560\D50C\B9AC\CF00\C774\C158\C758 \D0D0\C0C9 \B79C\B4DC\B9C8\D06C \B808\C774\BE14\C740 ''\C560\D50C\B9AC\CF00\C774\C158 \D0D0\C0C9''\C774 \C544\B2C8\B77C ''\C560\D50C\B9AC\CF00\C774\C158''\C774\C5B4\C57C \D569\B2C8\B2E4. \ADF8\B798\C57C \C2A4\D06C\B9B0 \B9AC\B354\AC00 ''\D0D0\C0C9''\C744 \B450 \BC88 \BC1C\C74C\D558\C9C0 \C54A\C2B5\B2C8\B2E4.</li>'),
'</ul>',
'</p>',
''))
,p_version_scn=>2565248
);
