,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<p>\C5EC\B35F \AC1C\C758 \C11C\B85C \B2E4\B978 \B79C\B4DC\B9C8\D06C \C720\D615\C744 \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4. \C5EC\B35F \AC1C \C911 \C77C\ACF1 \AC1C\B294 \D2B9\C815 \C758\BBF8\B97C \AC00\C9C0\BA70 \D2B9\C815 \C0C1\D669(\C608: \AC80\C0C9 \AE30\B2A5\C774 \D3EC\D568\B41C \C601\C5ED\C758 \ACBD\C6B0 "\AC80\C0C9", \D0D0\C0C9 \AE30\B2A5\C774 \D3EC\D568\B41C \C601\C5ED\C758 \ACBD\C6B0 "\D0D0\C0C9")\C5D0 \C801\D569\D569\B2C8\B2E4. \B9C8\C9C0\B9C9 \C720\D615\C740 "\C601\C5ED"\C73C\B85C, \D2B9\C815 \B79C\B4DC\B9C8\D06C\AC00 \C801\C808\D558\C9C0 \C54A\C9C0\B9CC \D398\C774\C9C0\C758 \B79C\B4DC\B9C8\D06C\B85C \D574\B2F9 \C601\C5ED\C744 \ACC4\C18D \D3EC\D568\D558\B824\B294 \ACBD\C6B0\C5D0 \C801\D569\D569\B2C8\B2E4.</p>'),
unistr('<p>\B79C\B4DC\B9C8\D06C\C5D0 \B300\D55C \C790\C138\D55C \B0B4\C6A9\C740 <a rel="noopener noreferrer" href="#SYSTEM_HELP_URL#CSH:pd-landmark-type" target="_blank">\D398\C774\C9C0 \AD6C\C870 - \B79C\B4DC\B9C8\D06C</a>\B97C \CC38\C870\D558\C2ED\C2DC\C624.</p>'),
''))
,p_version_scn=>2565329
);
