unistr('APEX\C5D0\C11C\B294 \C77C\BC18\C801\C73C\B85C \C560\D50C\B9AC\CF00\C774\C158 \B85C\ACE0, \C774\B984 \BC0F \D0D0\C0C9\D45C\C2DC\C904 \CF58\D2B8\B864\ACFC \AC19\C774 \C0C1\B2E8 \D45C\C2DC\C904 \C548\C5D0 \D3EC\D568\B41C \BAA8\B4E0 \AC83\C774 \B429\B2C8\B2E4.'),
unistr('(\ADF8\B7EC\B098 \C0AC\C6A9\C790 \C560\D50C\B9AC\CF00\C774\C158, \C0AC\C6A9 \C911\C778 \D14C\B9C8\B098 \D15C\D50C\B9AC\D2B8\C5D0 \B530\B77C \B2EC\B77C\C9C8 \C218 \C788\C2B5\B2C8\B2E4.)'),
unistr('<p>\D398\C774\C9C0\C5D0\B294 \B300\AC1C \D558\B098\C758 <code>banner</code> \B79C\B4DC\B9C8\D06C\B9CC \C788\ACE0, APEX \D398\C774\C9C0\C758 \AC00\C7A5 \C77C\BC18\C801\C778 \D328\D134\C740 \C774 <code>banner</code> \B79C\B4DC\B9C8\D06C\AC00'),
unistr('\D398\C774\C9C0 \D15C\D50C\B9AC\D2B8\C5D0\C11C \C628\B2E4\B294 \AC83\C785\B2C8\B2E4. \C989, APEX\C5D0\C11C \D398\C774\C9C0 \C601\C5ED\C744 <code>banner</code> \C601\C5ED\C73C\B85C \C815\C758\D558\B294 \AC83\C740 \B9E4\C6B0 \B4DC\BB45\B2C8\B2E4.</p>'),
''))
