,p_name=>'PE.PROPERTY.LINK_EXAMPLE.COMPONENT_PROPERTY.CLASSIC_REPORT_PRINT_ATTR.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\BCF4\ACE0\C11C \C601\C5ED\C740 \BCF4\ACE0\C11C \C601\C5ED \C544\B798\C5D0 \D45C\C2DC\B41C \D45C\C900 \C778\C1C4 \B9C1\D06C \B610\B294 \B2E8\CD94\B97C \C0AC\C6A9\D574\C11C \C778\C1C4\D560 \C218 \C788\C2B5\B2C8\B2E4. \B2E8\CD94\B97C \C0AC\C6A9\D558\B824\B294 \ACBD\C6B0 \B9C1\D06C \B808\C774\BE14\C744 \C81C\AC70\D558\ACE0 \B2E8\CD94 \B300\C0C1\C73C\B85C \C778\C1C4 URL\C5D0 \D45C\C2DC\B41C URL\C744 \C0AC\C6A9\D574\C11C \D398\C774\C9C0\C5D0\C11C \B2E8\CD94\B97C \C0DD\C131\D569\B2C8\B2E4.</p>'),
unistr('<p>\B2E8\CD94\B97C \C0AC\C6A9\D574\C11C \BCF4\ACE0\C11C \C601\C5ED\C744 \C778\C1C4\D558\BA74 \C138\C158 \C0C1\D0DC\B97C \C124\C815\D560 \C218 \C788\C2B5\B2C8\B2E4. \C774 \AE30\B2A5\C740 \C5EC\B7EC \AC00\C9C0 \CD9C\B825 \D615\C2DD(Word, Excel, PDF \B4F1)\C73C\B85C \C778\C1C4\B97C \C9C0\C6D0\D558\ACE0 \AC01 \C635\C158\C5D0 \B300\D574 \B2E8\CD94, \B9C1\D06C \B610\B294 \C774\BBF8\C9C0\B97C \D45C\C2DC\D558\B824\B294 \ACBD\C6B0\C5D0 \C720\C6A9\D569\B2C8\B2E4. \C774 \AD6C\D604\C744 \C704\D574\C11C\B294 \D56D\BAA9 \C635\C158\C5D0\C11C \D30C\C0DD\B41C \CD9C\B825 \D615\C2DD\C744 \C0AC\C6A9\D558\ACE0 \D56D\BAA9 \C774\B984 \BC0F \AC12\C744 \C778\C1C4 URL\C5D0 \D3EC\D568\C2DC\D0B5\B2C8\B2E4.</p>')))
,p_version_scn=>2565416
);
