,p_name=>'PE.PROPERTY.LINK_ICON.HELP'
,p_message_language=>'ko'
,p_message_text=>unistr('\B9C1\D06C\C5D0 \C0AC\C6A9\D560 HTML\C744 \C785\B825\D569\B2C8\B2E4. \C774\BBF8\C9C0 \D0DC\ADF8\B97C \C0AC\C6A9\D574\C11C \C774\BBF8\C9C0\B97C \D45C\C2DC\D558\AC70\B098 \AE30\BCF8 \C774\BBF8\C9C0 \BAA9\B85D\C5D0\C11C \C120\D0DD\D569\B2C8\B2E4. \C815\C758\B418\C9C0 \C54A\C558\C73C\BA74 \AE30\BCF8 \C544\C774\CF58\C774 \C0AC\C6A9\B429\B2C8\B2E4.')
