wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(115173492290665407)
,p_name=>'PE.PROPERTY.LINK_TARGET.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\BAA8\B2EC \B300\D654\C0C1\C790\B97C \D638\CD9C\D558\B824\B294 \B300\C0C1\C744 \B204\B985\B2C8\B2E4. \B9C1\D06C \C5F4\C744 \B204\B97C \B54C \D638\CD9C\D560 \C0AC\C6A9\C790\C815\C758 \B300\C0C1\C744 \C785\B825\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
unistr('        <p>\C694\AD6C\C0AC\D56D\C5D0 \B530\B77C \B9C1\D06C \C791\C131\AE30 - \B300\C0C1\C5D0\C11C \C801\D569\D55C \C720\D615\C744 \C120\D0DD\D569\B2C8\B2E4.'),
'        <dl>',
unistr('        <dt>\C774 \C560\D50C\B9AC\CF00\C774\C158\C758 \D398\C774\C9C0</dt>'),
unistr('        <dd>\B2E4\C74C\C744 \C785\B825\D569\B2C8\B2E4.'),
'        <ul>',
unistr('        <li>\D398\C774\C9C0 - \C774\B3D9\D560 \D398\C774\C9C0 \BC88\D638 \B610\B294 \D398\C774\C9C0 \BCC4\CE6D\C744 \C785\B825\D569\B2C8\B2E4. \C120\D0DD \BAA9\B85D\C5D0\C11C \D398\C774\C9C0 \BC88\D638\B97C \C120\D0DD\D560 \C218\B3C4 \C788\C2B5\B2C8\B2E4.</li>'),
unistr('        <li>\D56D\BAA9 \C124\C815: \C774\B984 - \C138\C158 \C0C1\D0DC\C5D0\C11C \C124\C815\D560 \D398\C774\C9C0 \D56D\BAA9(<code>P3_ID</code>), \C560\D50C\B9AC\CF00\C774\C158 \D56D\BAA9(<code>LAST_PAGE</code>) \B610\B294 \B300\D654\C2DD \BCF4\ACE0\C11C \D544\D130(<code>IR_EMPNO</code>)\B97C \C785\B825\D558\AC70\B098 \C120\D0DD\D569\B2C8\B2E4.</li>'),
unistr('        <li>\D56D\BAA9 \C124\C815: \AC12 - \BCF4\ACE0\C11C \C5F4(<code>#ID#</code>)\C744 \C785\B825 \B610\B294 \C120\D0DD\D558\AC70\B098, \C560\D50C\B9AC\CF00\C774\C158 \B610\B294 \D398\C774\C9C0 \D56D\BAA9(<code>&P2_EMPNO.</code>)\C744 \C785\B825\D558\AC70\B098, \C815\C801 \AC12(<code>2</code>)\C744 \C785\B825\D569\B2C8\B2E4.</li>'),
unistr('        <li>\CE90\C2DC \BE44\C6B0\AE30 - \C9C0\C6B8 \D398\C774\C9C0 \BC88\D638(<code>2,3</code>), \D56D\BAA9(<code>P3_EMPNO,LAST_PAGE</code>) \BC0F \BCF4\ACE0\C11C \C124\C815\C758 \CF64\B9C8\B85C \AD6C\BD84\B41C \BAA9\B85D\C744 \C785\B825\D569\B2C8\B2E4. \BCF4\ACE0\C11C\C5D0 \B300\D55C \D398\C774\C9C0 \BC88\D638 \B9E4\AE40\C744 \C7AC\C124\C815\D558\B824\BA74 <code>RP</code>\B97C \C785\B825\D569\B2C8\B2E4. \B300\D654\C2DD \BCF4\ACE0\C11C \C124\C815\C744 \C9C0\C6B0\AC70\B098 \C7AC\C124\C815\D558\B824\BA74 <code>CIR</code> \B610\B294 <code>RIR</code>\C744 \C785\B825\D569\B2C8\B2E4.</li>'),
unistr('        <li>\D398\C774\C9C0 \BC88\D638 \B9E4\AE40 \C7AC\C124\C815 - \B300\C0C1 \D398\C774\C9C0\C758 \BCF4\ACE0\C11C\C5D0 \B300\D574 \D398\C774\C9C0 \BC88\D638 \B9E4\AE40\C744 \CCAB\BC88\C9F8 \B808\CF54\B4DC \C9D1\D569\C73C\B85C \C7AC\C124\C815\D558\B824\BA74 [\C608]\B97C \C120\D0DD\D569\B2C8\B2E4. \C774\B807\AC8C \D558\BA74 \CE90\C2DC \BE44\C6B0\AE30\C5D0\C11C <code>RP</code>\B97C \C804\B2EC\D558\B294 \AC83\ACFC \B3D9\C77C\D55C \D6A8\ACFC\AC00 \C788\C2B5\B2C8\B2E4.</li>'),
unistr('        <li>\ACE0\AE09: \C694\CCAD - \C0AC\C6A9\D560 \C694\CCAD\C744 \C785\B825\D569\B2C8\B2E4.</li>'),
'        </ul>',
