,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C2A4\D06C\B9B0 \B9AC\B354\C640 \AC19\C740 \BCF4\C870 \AE30\C220 \C0AC\C6A9\C790\AC00 \CF58\D150\CE20\B97C \D6A8\ACFC\C801\C73C\B85C \D0D0\C0C9\D558\ACE0 \C774\D574\D558\B824\BA74 \C561\C138\C2A4 \AC00\B2A5\D55C \B9C1\D06C \D14D\C2A4\D2B8\AC00 \D544\C218\C785\B2C8\B2E4.</p>'),
unistr('<strong>\CD5C\C801\C758 \BC29\BC95:</strong>'),
'<ol>',
unistr('<li><strong>\AC04\ACB0\C131:</strong> \D544\C694\D55C \C815\BCF4\B97C \C804\B2EC\D558\BA74\C11C \B9C1\D06C \D14D\C2A4\D2B8\B97C \AC04\ACB0\D558\AC8C \C720\C9C0\D569\B2C8\B2E4. \AC04\ACB0\C131\ACFC \C124\BA85\C131 \C0AC\C774\C758 \ADE0\D615\C744 \BAA9\D45C\B85C \D569\B2C8\B2E4.</li>'),
unistr('<li><strong>\C811\ADFC\C131 \C18D\C131:</strong> \BCF4\ACE0\C11C \C5F4 \D589 \BA38\B9AC\AE00\C774 \C815\C758\B418\C5B4 \C788\C5B4\C57C \D569\B2C8\B2E4. \C774 \C18D\C131\C744 \C815\C758\D558\BA74 \D45C \D615\C2DD \B370\C774\D130 \B0B4\C5D0\C11C \BA85\D655\D55C \BC29\D5A5 \C9C0\C810\C774 \C81C\ACF5\B418\C5B4 \C2A4\D06C\B9B0 \B9AC\B354 \C0AC\C6A9\C790\C758 \D0D0\C0C9 \D658\ACBD\C774 \D5A5\C0C1\B429\B2C8\B2E4.</li>'),
unistr('<li><strong>\BC18\BCF5\B418\B294 \B9C1\D06C:</strong> \C77C\BC18\C801\C778 \BCF4\ACE0\C11C\C5D0\C11C \AC01 \D589\C5D0\B294 \D3B8\C9D1 \C635\C158\ACFC \AC19\C740 \BC18\BCF5 \B9C1\D06C\AC00 \C788\B294 \ACBD\C6B0\AC00 \B9CE\C2B5\B2C8\B2E4. \C774\B7EC\D55C \ACBD\C6B0 \AC00\C7A5 \D6A8\ACFC\C801\C778 \B9C1\D06C \D14D\C2A4\D2B8\B294 ''\D3B8\C9D1''\C774\BA70 \BA85\D655\D55C \D589 \BA38\B9AC\AE00\ACFC \C30D\C744 \C774\B8F9\B2C8\B2E4.</li>'),
'</ol>',
unistr('<p>\B9C1\D06C \D14D\C2A4\D2B8\C5D0 \B300\D574 \C774\B7EC\D55C \CD5C\C801\C758 \BC29\BC95\C744 \B530\B974\BA74 \C7A5\C560\AC00 \C788\B294 \C0AC\C6A9\C790\B97C \BE44\B86F\D55C \BAA8\B4E0 \C0AC\C6A9\C790\B97C \C704\D574 \BCF4\B2E4 \D3EC\AD04\C801\C774\ACE0 \C561\C138\C2A4 \AC00\B2A5\D55C \D0D0\C0C9 \D658\ACBD\C744 \C0DD\C131\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>')))
,p_version_scn=>2565249
);
