wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(115049359402665371)
,p_name=>'PE.PROPERTY.LOST_UPDATE_CHECK_TYPE.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C190\C2E4\B41C \C5C5\B370\C774\D2B8\B85C\BD80\D130 \B370\C774\D130\B97C \BCF4\D638\D558\AE30 \C704\D55C \BC29\BC95\C744 \C120\D0DD\D569\B2C8\B2E4.'),
unistr('		\C190\C2E4\B41C \C5C5\B370\C774\D2B8\B294 2\BA85 \C774\C0C1\C774 \B3D9\C77C\D55C \B370\C774\D130\B97C \C5C5\B370\C774\D2B8\D558\B824\ACE0 \C2DC\B3C4\D558\ACE0 \CD5C\C885 \C5C5\B370\C774\D2B8\AC00 \CCAB\BC88\C9F8 \C0AC\C6A9\C790\C758 \C5C5\B370\C774\D2B8\B97C \ACB9\CCD0\C4F0\BA74\C11C \BCC0\ACBD\C0AC\D56D\C744 \C800\C7A5\D560 \B54C \BC1C\C0DD\D569\B2C8\B2E4.'),
unistr('		\C774 \C0C1\D669\C774 \BC1C\C0DD\D558\C9C0 \C54A\B3C4\B85D \D558\AE30 \C704\D574 \C5C5\B370\C774\D2B8\C5D0\C11C\B294 \B370\C774\D130\BCA0\C774\C2A4\C758 \AE30\C874 \C5F4 \AC12\ACFC \B808\CF54\B4DC\AC00 \CC98\C74C\C5D0 \C9C8\C758\B420 \B54C \AC80\C0C9\B41C \AC12\C744 \BE44\AD50\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
unistr('		<p>\C608:'),
'          <ol>',
unistr('            <li>\C0AC\C6A9\C790 A\AC00 \C9C1\C6D0(EMP) \B808\CF54\B4DC\B97C \C9C8\C758\D569\B2C8\B2E4.</li>'),
unistr('		    <li>\C0AC\C6A9\C790 B\AC00 \B3D9\C77C\D55C \C9C1\C6D0 \B808\CF54\B4DC\B97C \C9C8\C758\D569\B2C8\B2E4.</li>'),
unistr('		    <li>\C0AC\C6A9\C790 B\AC00 EMPNO = 7839\C5D0 \B300\D55C \C9C1\C6D0 \C138\BD80\C815\BCF4\B97C \C5C5\B370\C774\D2B8\D558\ACE0 \BCC0\ACBD\C0AC\D56D\C744 \B370\C774\D130\BCA0\C774\C2A4\C5D0 \C801\C6A9(\CEE4\BC0B)\D569\B2C8\B2E4.</li>'),
unistr('		    <li>\C0AC\C6A9\C790 A\AC00 EMPNO = 7839\C5D0 \B300\D55C \C9C1\C6D0 \C138\BD80\C815\BCF4\B97C \C5C5\B370\C774\D2B8\D558\ACE0 \BCC0\ACBD\C0AC\D56D\C744 \B370\C774\D130\BCA0\C774\C2A4\C5D0 \C801\C6A9\D558\B824\ACE0 \C2DC\B3C4 \C911\C785\B2C8\B2E4.</li>'),
'          </ol>',
unistr('          \C0AC\C6A9\C790 A\AC00 \B3D9\C77C\D55C \B808\CF54\B4DC\B97C \C131\ACF5\C801\C73C\B85C \C5C5\B370\C774\D2B8\D560 \ACBD\C6B0 \C0AC\C6A9\C790 B\C758 \BCC0\ACBD\C0AC\D56D\C740 \C190\C2E4\B429\B2C8\B2E4.</p>'),
unistr('         <p>\C0AC\C6A9\C790 A\AC00 \C9C1\C6D0 \B808\CF54\B4DC\B97C \C800\C7A5\D558\B824\ACE0 \C2DC\B3C4 \C911\C77C \B54C \B370\C774\D130\BCA0\C774\C2A4\C758 \B370\C774\D130\B294 \C0AC\C6A9\C790 A\AC00 \CC98\C74C\C5D0 \C9C8\C758\D588\C744 \B54C\C640 \B2E4\B985\B2C8\B2E4.'),
unistr('		  \C704\C758 1\B2E8\ACC4\C5D0\C11C \C0AC\C6A9\C790 A\AC00 \CC98\C74C\C5D0 \C9C8\C758\D55C \C5F4 \AC12\C744 \CEA1\CC98\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('		  \ADF8\B7F0 \B2E4\C74C \C704\C758 4\B2E8\ACC4\C5D0\C11C \AC12\C744 \B370\C774\D130\BCA0\C774\C2A4\C758 \D604\C7AC \AC12\ACFC \BE44\AD50\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('		  \B370\C774\D130\BCA0\C774\C2A4 \AC12\C774 3\B2E8\ACC4\C5D0\C11C \C0AC\C6A9\C790 B\C5D0 \C758\D574 \C5C5\B370\C774\D2B8\B418\C5C8\C73C\BBC0\B85C \C774 \BE44\AD50\B294 \C0AC\C6A9\C790 A\C5D0 \B300\D55C \C624\B958\B97C \BC1C\C0DD\C2DC\D0B5\B2C8\B2E4.'),
unistr('		  \ADF8\B7EC\BA74 \D55C \C0AC\C6A9\C790\AC00 \B2E4\B978 \C0AC\C6A9\C790\C758 \BCC0\ACBD\C0AC\D56D\C744 \B3D9\C77C\D55C \D589\C5D0 \ACB9\CCD0\C4F0\C9C0 \BABB\D558\AC8C \B429\B2C8\B2E4.</p>'),
unistr('		  <p>\CC38\ACE0 - \C190\C2E4\B41C \C5C5\B370\C774\D2B8 \C720\D615\C740 \D574\B2F9\D558\B294 \D504\B85C\C138\C2A4\C778 \B300\D654\C2DD \ADF8\B9AC\B4DC - \C790\B3D9 \D589 \D504\B85C\C138\C2F1(DML)\C5D0\C11C <strong>\C190\C2E4\B41C \C5C5\B370\C774\D2B8 \BC29\C9C0</strong>\AC00 \C0AC\C6A9\C73C\B85C \C124\C815\B41C \ACBD\C6B0\C5D0\B9CC \C0AC\C6A9\B429\B2C8\B2E4.</p>')))
,p_version_scn=>2565385
);
