,p_name=>'PE.PROPERTY.MAP_CLUSTER_POINT_FEATURE_FILL_COLOR.COMPONENT_PROPERTY.MAP_LAYER.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\BAA8\B4E0 \C0AC\C6A9\C790\C758 \AC00\C2DC\C131\ACFC \C720\C6A9\C131\C744 \D5A5\C0C1\C2DC\D0A4\B824\BA74 \D3EC\C778\D2B8 \D074\B7EC\C2A4\D130\D654 \CC44\C6B0\AE30 \C0C9\C0C1\C774 \D2B9\C815 \AE30\C900\C744 \CDA9\C871\D574\C57C \D569\B2C8\B2E4.</p>'),
unistr('<strong>\CD5C\C801\C758 \BC29\BC95:</strong><ol>'),
unistr('<li><strong>\B300\BE44 \BE44\C728:</strong> \D3EC\C778\D2B8 \D074\B7EC\C2A4\D130\D654 \CC44\C6B0\AE30\B294 \BC30\ACBD\ACFC \BE44\AD50\D558\C5EC \CD5C\C18C\D55C (3:1)\C758 \B300\BE44 \BE44\C728\C744 \AC00\C838\C57C \D569\B2C8\B2E4. \ADF8\B7EC\BA74 \C2DC\AC01 \C7A5\C560\AC00 \C788\B294 \C0AC\C6A9\C790\AC00 \D074\B7EC\C2A4\D130\D654\B41C \D3EC\C778\D2B8\B97C \D6A8\ACFC\C801\C73C\B85C \C2DD\BCC4\D560 \C218 \C788\C2B5\B2C8\B2E4.</li>'),
unistr('<li><strong>\D45C\C900 \CC44\C6B0\AE30 \C0C9\C0C1\ACFC\C758 \AD6C\BCC4:</strong> \D3EC\C778\D2B8 \D074\B7EC\C2A4\D130\D654 \CC44\C6B0\AE30 \C0C9\C0C1\C740 \D45C\C900 \CC44\C6B0\AE30 \C0C9\C0C1\ACFC\B3C4 \AD6C\BCC4 \AC00\B2A5\D574\C57C \D569\B2C8\B2E4. \C774\B7EC\D55C \AD6C\BCC4\C740 \C0AC\C6A9\C790\AC00 \D074\B7EC\C2A4\D130\D654\B41C \D3EC\C778\D2B8\C640 \D45C\C900 \B370\C774\D130 \D3EC\C778\D2B8\B97C \C27D\AC8C \AD6C\BCC4\D558\C5EC \B370\C774\D130 \C774\D574\B825\ACFC \C0C1\D638\C791\C6A9\C744 \D5A5\C0C1\C2DC\D0A4\B294 \B370 \C911\C694\D569\B2C8\B2E4.</li>'),
'</ol>',
unistr('<p>\C774\B7EC\D55C \C9C0\CE68\C744 \C900\C218\D568\C73C\B85C\C368 \C2DC\AC01\C801 \B2A5\B825\C5D0 \AD00\ACC4\C5C6\C774 \BAA8\B4E0 \C0AC\C6A9\C790\C5D0\AC8C \BCF4\B2E4 \D3EC\AD04\C801\C774\ACE0 \C561\C138\C2A4 \AC00\B2A5\D55C \D658\ACBD\C744 \C81C\ACF5\D558\AE30 \C704\D574 \B178\B825\D558\ACE0 \C788\C2B5\B2C8\B2E4.</p>')))
,p_version_scn=>2565249
);
