'<ul>',
unistr('<li>\C0AC\C6A9\C790\C758 \C0C9\B9F9 \C720\BCD1\B960\C744 \ACE0\B824\D558\ACE0 \C0AC\C6A9\C790\C758 \C694\AD6C\B97C \ACE0\B824\D558\C5EC \B514\C790\C778\D569\B2C8\B2E4.</li>'),
unistr('<li>\C815\BCF4\B97C \C804\B2EC\D558\AE30 \C704\D574 \C0C9\C0C1\C5D0\B9CC \C758\C874\D558\C9C0 \B9C8\C2ED\C2DC\C624. \C0C9\C0C1 \AD6C\BCC4\C744 \BCF4\C644\D558\AE30 \C704\D574 \D328\D134\C774\B098 \C9C8\AC10\ACFC \AC19\C740 \B2E4\B978 \C2DC\AC01\C801 \B2E8\C11C\B97C \D1B5\D569\D569\B2C8\B2E4.</li>'),
