,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\B9F5\C758 \D68D \C0C9\C0C1\C740 \C2DC\B825\C774 \C57D\AC04 \B0AE\C740 \AC1C\C778\C774 \B9F5\C5D0\C11C \C778\C811\D55C \C0C9\C0C1 \C138\ADF8\BA3C\D2B8 \AC04\C758 \ACBD\ACC4\B97C \D6A8\ACFC\C801\C73C\B85C \AD6C\BD84\D560 \C218 \C788\B3C4\B85D \D558\B294 \C5ED\D560\C744 \D569\B2C8\B2E4.<p>'),
unistr('<strong>\CD5C\C801\C758 \BC29\BC95:</strong>'),
'<ol>',
unistr('<li>\C0C9\C0C1 \C120\D0DD \ACE0\B824\C0AC\D56D:'),
'<ul>',
unistr('<li>\C5EC\B7EC \C0C9\C0C1\C774 \D3EC\D568\B41C \B9F5\C758 \C0C9\C0C1\C744 \C120\D0DD\D560 \B54C \C778\C811\D55C \C0C9\C0C1 \AC04\C758 \B300\BE44 \BE44\C728\C744 \ACE0\B824\D574\C57C \D569\B2C8\B2E4.</li>'),
unistr('<li>\BA85\D655\D55C \AD6C\BD84\C744 \C704\D574 \C778\C811\D55C \C0C9\C0C1 \AC04\C758 \B300\BE44 \BE44\C728\C774 \CD5C\C18C\D55C 3:1\C774\C5B4\C57C \D569\B2C8\B2E4.</li></ul></li>'),
unistr('<li>\D14C\C2A4\D2B8 \BC0F \C870\C815 \D504\B85C\C2DC\C800:'),
'<ul>',
unistr('<li>\CD5C\C18C \B300\BE44 \BE44\C728 \C694\AD6C\C0AC\D56D\C774 \C900\C218\B418\B3C4\B85D \C811\ADFC\C131 \D14C\C2A4\D2B8 \D234 \B610\B294 \C218\B3D9 \AC80\C0AC\B97C \D65C\C6A9\D569\B2C8\B2E4.</li>'),
unistr('<li>\C778\C811\D55C \C0C9\C0C1\C758 \B300\BE44 \BE44\C728\C774 3:1 \BBF8\B9CC\C73C\B85C \B5A8\C5B4\C9C0\BA74 \AC00\C2DC\C131 \D5A5\C0C1\C744 \C704\D55C \D574\ACB0 \C870\CE58\B97C \CDE8\D569\B2C8\B2E4.</li>'),
unistr('<li>\C778\C811\D55C \C138\ADF8\BA3C\D2B8\B97C \C2DC\AC01\C801\C73C\B85C \AD6C\BD84\D558\ACE0 \BA85\D655\C131\C744 \B192\C774\AE30 \C704\D574 \B300\BE44\B418\B294 \C0C9\C0C1\C73C\B85C \D14C\B450\B9AC\B97C \CD94\AC00\D558\B294 \AC83\C774 \C88B\C2B5\B2C8\B2E4.</li></ul></li>'),
unistr('<li>\C0C9\B9F9 \ACE0\B824\C0AC\D56D:'),
'<ul>',
unistr('<li>\C0AC\C6A9\C790\C758 \C0C9\B9F9 \C720\BCD1\B960\C744 \ACE0\B824\D558\ACE0 \C0AC\C6A9\C790\C758 \C694\AD6C\B97C \ACE0\B824\D558\C5EC \B514\C790\C778\D569\B2C8\B2E4.</li>'),
unistr('<li>\C815\BCF4\B97C \C804\B2EC\D558\AE30 \C704\D574 \C0C9\C0C1\C5D0\B9CC \C758\C874\D558\C9C0 \B9C8\C2ED\C2DC\C624. \C0C9\C0C1 \AD6C\BCC4\C744 \BCF4\C644\D558\AE30 \C704\D574 \D328\D134\C774\B098 \C9C8\AC10\ACFC \AC19\C740 \B2E4\B978 \C2DC\AC01\C801 \B2E8\C11C\B97C \D1B5\D569\D569\B2C8\B2E4.</li>'),
