,p_name=>'PE.PROPERTY.MAP_REGION_STATUS_ITEM.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\D398\C774\C9C0 \D56D\BAA9\C744 \C120\D0DD\D558\BA74 \B9F5 \C601\C5ED\C774 \D56D\C0C1 \D604\C7AC \B9F5 \ACBD\ACC4 \C0C1\C790\B97C \C774 \D56D\BAA9\C758 \AC12\C5D0 \B530\B77C GeoJSON \D615\C2DD\C73C\B85C \C720\C9C0\D569\B2C8\B2E4. \C774\AC83\C740 \B9F5\C744 \B2E4\B978 APEX \AD6C\C131\C694\C18C(\C608: \AE30\BCF8 \B610\B294 \B300\D654\C2DD \BCF4\ACE0\C11C)\C5D0 \C811\C18D\D558\B294 \B370 \C720\C6A9\D569\B2C8\B2E4. \ACBD\ACC4 \C0C1\C790 \D56D\BAA9\C758 \B0B4\C6A9\C740 \B2E4\B978 \AD6C\C131\C694\C18C\C5D0\C11C \ACF5\AC04 \C9C8\C758\B97C \C218\D589\D558\AC70\B098 \B9F5\C5D0 \D45C\C2DC \AC00\B2A5\D55C \B370\C774\D130\B9CC \D45C\C2DC\D558\AE30 \C704\D55C \C6A9\B3C4\B85C \C0AC\C6A9\B420 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
unistr('<p>\C77C\BD80 \B9F5 \C774\B3D9 \B610\B294 \D655\B300/\CD95\C18C \B808\BCA8 \BCC0\ACBD \D6C4 \ACBD\ACC4 \C0C1\C790 \D56D\BAA9\C758 \CF58\D150\CE20 \C608:</p>'),
'<pre>',
'{',
'  "type": "Polygon",',
'  "coordinates": [[',
'                    [-5.499,46.380],',
'                    [ 8.187,46.380],',
'                    [ 8.187,49.550],',
'                    [-5.499,49.550],',
'                    [-5.499,46.380]]]',
'}',
'</pre>',
'<p>',
unistr('<strong>\C0C8\B85C\ACE0\CE68</strong> \B3D9\C801 \C791\C5C5\C744 \C0AC\C6A9\D558\C5EC \B9F5\C744 \BCF4\ACE0\C11C \C601\C5ED\C5D0 \C5F0\ACB0\D560 \C218 \C788\C2B5\B2C8\B2E4. \BCF4\ACE0\C11C \C601\C5ED\C740 \ACF5\AC04 \D544\D130\B97C \C801\C6A9\D558\C5EC \B9F5\C5D0\C11C\B3C4 \D45C\C2DC \AC00\B2A5\D55C \ACB0\ACFC\B9CC \D45C\C2DC\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
unistr('<p>\BCF4\ACE0\C11C \C9C8\C758 \C608:</p>'),
'<pre>',
'select [column1],',
'       [column2],',
'       ...',
'  from ...',
' where sdo_anyinteract(',
'           [geometry-column],',
'           sdo_util.from_geojson( :[item-name-of-bounding-box-item] )',
'       ) = ''TRUE''',
'   and ...',
'</pre>'))
,p_version_scn=>2565439
);
