wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(114910521631665330)
,p_name=>'PE.PROPERTY.OPTIMIZER_HINT.EXAMPLES'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<dl>',
'<dt><pre>INDEX (employees emp_department_ix)</pre></dt>',
unistr('<dd><code>employee</code> \D14C\C774\BE14\C5D0 \C561\C138\C2A4\D560 \B54C <code>emp_department_ix</code></dd> \C778\B371\C2A4\B97C \C0AC\C6A9\D574 \BCF4\C2ED\C2DC\C624.'),
'<dt><pre>WITH_PLSQL</pre></dt>',
unistr('<dd>SQL \C9C8\C758 \B0B4\C5D0\C11C <code>WITH plsql_declarations</code> \C808\C744 \C0AC\C6A9\C73C\B85C \C124\C815\D569\B2C8\B2E4.</dd>'),
'</dl>',
unistr('<h5>\B2E4\C74C <em>APEX \C758\C0AC \D78C\D2B8</em>\B97C \C0AC\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4.</h5>'),
'<dl>',
'<dt><pre>APEX$USE_OFFSET_PAGINATION</pre></dt>',
unistr('<dd>\D398\C774\C9C0 \B9E4\AE40 SQL\C744 \C0DD\C131\D560 \B54C <strong>ROW_NUMBER</strong> \BD84\C11D \D568\C218 \B300\C2E0, <strong>OFFSET m ROWS FETCH n ROWS</strong> (SQL2008) \AD6C\BB38\C744 \C0AC\C6A9\D569\B2C8\B2E4. \C2E4\D589\B41C \C9C8\C758\B294 \D604\C7AC \AD6C\C131\C694\C18C \D398\C774\C9C0\C5D0 \B300\D574 \AD00\C2EC \D589\B9CC \BC18\D658\D569\B2C8\B2E4.</dd>'),
'<dt><pre>APEX$USE_ROWNUM_PAGINATION</pre></dt>',
unistr('<dd>\D398\C774\C9C0 \B9E4\AE40 SQL\C744 \C0DD\C131\D560 \B54C <strong>ROW_NUMBER</strong> \BD84\C11D \D568\C218 \B300\C2E0, <strong>ROWNUM</strong> \C758\C0AC \C5F4\C744 \C0AC\C6A9\D569\B2C8\B2E4. \C2E4\D589\B41C \C9C8\C758\B294 \D604\C7AC \AD6C\C131\C694\C18C \D398\C774\C9C0\C5D0 \B300\D574 \AD00\C2EC \D589\B9CC \BC18\D658\D569\B2C8\B2E4.</dd>'),
'<dt><pre>APEX$USE_NO_PAGINATION</pre></dt>',
unistr('<dd>\D398\C774\C9C0 \B9E4\AE40 SQL\C744 \C791\C131\D558\C9C0 \C54A\C2B5\B2C8\B2E4. \AD6C\C131\C694\C18C\B294 \D56D\C0C1 \CCAB\BC88\C9F8 \D589\C5D0\C11C \C778\CD9C\C744 \C2DC\C791\D558\ACE0, \D604\C7AC \D398\C774\C9C0\B294 \D589\C744 \AC74\B108\B6F0\ACE0 \B9C8\C9C0\B9C9 \AD00\C2EC \D589\C744 \C778\CD9C\D55C \D6C4 \C815\C9C0\D558\C5EC \D45C\C2DC\B429\B2C8\B2E4.</dd>'),
'<dt><pre>APEX$USE_NO_BULK_FETCH</pre></dt>',
unistr('<dd>\C774 \C9C8\C758\C5D0 \B300\B7C9 \C778\CD9C\C744 \C0AC\C6A9\D558\C9C0 \C54A\C2B5\B2C8\B2E4.</dd>'),
'<dt><pre>APEX$USE_NO_GROUPING_SETS</pre></dt>',
unistr('<dd>\D328\C2EF \AC80\C0C9 \B610\B294 \C2A4\B9C8\D2B8 \D544\D130\C5D0 \B300\D574 <strong>GROUPING SETS</strong> SQL \C808\C744 \C0AC\C6A9\D558\C9C0 \C54A\C2B5\B2C8\B2E4. \B300\C2E0 \AC1C\BCC4 \C9C8\C758\B97C \C0AC\C6A9\D558\C5EC \AC01 \D328\C2EF/\D544\D130\C758 \AC1C\C218\B97C \ACC4\C0B0\D558\ACE0 UNION ALL\ACFC \ACB0\D569\D569\B2C8\B2E4.</dd>'),
'</dl>'))
,p_version_scn=>2565369
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(114910477786665330)
,p_name=>'PE.PROPERTY.OPTIMIZER_HINT.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>&PRODUCT_NAME.\C5D0\C11C \C0DD\C131\B41C SQL \C9C8\C758 \C2E4\D589 \C2DC \CD5C\C0C1\C704 \B808\BCA8 \BA85\B839\BB38\C5D0 \CD94\AC00\B418\B294 Oracle \CD5C\C801\AE30 \D78C\D2B8\B97C \C785\B825\D569\B2C8\B2E4.'),
unistr('        \D78C\D2B8\B294 \CD5C\C801\AE30\C5D0 \C804\B2EC\B418\B294 \BA85\B839\C785\B2C8\B2E4. SQL \C791\C131 \C2DC \CD5C\C801\AE30\C5D0 \C54C\B824\C9C0\C9C0 \C54A\C740 \B370\C774\D130\C5D0 \B300\D55C \C815\BCF4\AC00 \D30C\C545\B418\AE30\B3C4 \D569\B2C8\B2E4. \C774 \ACBD\C6B0 \D78C\D2B8\B97C \D1B5\D574 \C77C\BC18\C801\C73C\B85C \CD5C\C801\AE30\AC00 \ACB0\C815\D558\B294 \C0AC\D56D\C744 \C0AC\C6A9\C790\AC00 \ACB0\C815\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('        \CD5C\C801\AE30\AC00 \BCF4\B2E4 \B9CE\C740 \BE44\C6A9\C774 \B4DC\B294 \AC83\C73C\B85C \D655\C778\B41C \ACC4\D68D\C744 \C120\D0DD\D558\B294 \ACBD\C6B0\B3C4 \C788\AE30 \B54C\BB38\C785\B2C8\B2E4.</p>'),
unistr('        <p>\C608\B97C \B4E4\C5B4, \D2B9\C815 \C778\B371\C2A4\AC00 \D2B9\C815 \C9C8\C758\C5D0 \B300\D574 \BCF4\B2E4 \B9CE\C774 \C120\D0DD\B428\C744 \C54C\ACE0 \C788\C744 \ACBD\C6B0 \C774 \C815\BCF4\B97C \AE30\BC18\C73C\B85C \CD5C\C801\AE30\BCF4\B2E4 \D6A8\C728\C801\C778 \C2E4\D589 \ACC4\D68D\C744 \C120\D0DD\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('        \C774\B7EC\D55C \ACBD\C6B0 \D78C\D2B8\B97C \C0AC\C6A9\D558\C5EC \CD5C\C801\AE30\AC00 \CD5C\C801\C758 \C2E4\D589 \ACC4\D68D\C744 \C0AC\C6A9\D558\B3C4\B85D \AC15\C81C \C801\C6A9\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>')))
,p_version_scn=>2565369
);
