,p_name=>'PE.PROPERTY.PAGE_TEMPLATE.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C774 \D398\C774\C9C0\C758 \BAA8\C591\ACFC \B808\C774\C544\C6C3\C744 \C815\C758\D560 \D398\C774\C9C0 \D15C\D50C\B9AC\D2B8\B97C \C120\D0DD\D569\B2C8\B2E4.</p>'),
unistr('        <p>\D398\C774\C9C0 \D15C\D50C\B9AC\D2B8\B294 \C560\D50C\B9AC\CF00\C774\C158 \D14C\B9C8\C5D0\C11C \C815\C758\B429\B2C8\B2E4.'),
unistr('        \D398\C774\C9C0\AC00 \C0DD\C131\B418\BA74 \D15C\D50C\B9AC\D2B8\B294 <em>\D14C\B9C8 \AE30\BCF8\AC12</em>\C73C\B85C \C790\B3D9\C73C\B85C \C124\C815\B429\B2C8\B2E4. \C774 \C124\C815\C5D0\C11C\B294 \D604\C7AC \D14C\B9C8\C5D0 \C815\C758\B41C \AE30\BCF8 \D398\C774\C9C0 \D15C\D50C\B9AC\D2B8\B97C \C0AC\C6A9\D558\C5EC \D398\C774\C9C0\B97C \B80C\B354\B9C1\D569\B2C8\B2E4.'),
unistr('        \C5EC\AE30\C11C \C120\D0DD\D558\BA74 \AE30\BCF8 \D398\C774\C9C0 \D15C\D50C\B9AC\D2B8\B294 \BB34\D6A8\D654\B429\B2C8\B2E4.</p>'),
unistr('        <p>\B300\BD80\BD84\C758 \D14C\B9C8\C5D0\B294 \D2B9\C815 \C6A9\B3C4(\C608: \CE21\BA74 \C5F4, \B85C\ADF8\C778 \D398\C774\C9C0, \B300\D654\C0C1\C790 \D398\C774\C9C0 \B4F1\C744 \D3EC\D568\D558\B294 \CF58\D150\CE20 \D45C\C2DC)\C758 \D398\C774\C9C0 \D15C\D50C\B9AC\D2B8\AC00 \D3EC\D568\B418\C5B4 \C788\C2B5\B2C8\B2E4.<br>'),
unistr('        \BC94\C6A9 \D14C\B9C8\B294 \B2E4\C74C\ACFC \AC19\C740 \D398\C774\C9C0 \D15C\D50C\B9AC\D2B8\B97C \C81C\ACF5\D569\B2C8\B2E4.'),
'          <dl>',
unistr('            <dt>\D45C\C900</dt>'),
unistr('              <dd>\AE30\BCF8 \D398\C774\C9C0 \D15C\D50C\B9AC\D2B8\C785\B2C8\B2E4. \D654\BA74 \C790\C0B0\C744 \CD5C\B300\D654\D558\B294 \AC83\C774 \C88B\C740 \D648 \D398\C774\C9C0, \B300\C2DC\BCF4\B4DC, \B300\C6A9\B7C9 \BCF4\ACE0\C11C \BC0F \AE30\D0C0 \B808\C774\C544\C6C3\C5D0 \C801\D569\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\C67C\CABD \C5F4</dt>'),
unistr('              <dd>\AC80\C0C9 \BC0F \D544\D130 \C601\C5ED\C744 \BC30\CE58\D560 \C218 \C788\B294 \C2AC\B86F\C744 \C67C\CABD\C5D0 \C81C\ACF5\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\C624\B978\CABD \C5F4</dt>'),
unistr('              <dd>\C791\C5C5 \C9C0\D5A5 \CF58\D2B8\B864(\C608: \B2E8\CD94, \BAA9\B85D)\C744 \D45C\C2DC\D560 \C218 \C788\B294 \CD95\C18C \AC00\B2A5\D55C \C2AC\B86F\C744 \C624\B978\CABD\C5D0 \C81C\ACF5\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\C67C\CABD \BC0F \C624\B978\CABD \C5F4</dt>'),
unistr('              <dd>\B9E4\C6B0 \BCF5\C7A1\D55C \D398\C774\C9C0\C5D0 \C801\D569\D55C \C67C\CABD \C5F4\ACFC \CD95\C18C \AC00\B2A5\D55C \C624\B978\CABD \C5F4\C744 \BAA8\B450 \C81C\ACF5\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\B85C\ADF8\C778</dt>'),
unistr('              <dd>\C560\D50C\B9AC\CF00\C774\C158 \B85C\ADF8\C778 \D398\C774\C9C0\C5D0\B9CC \C0AC\C6A9\B429\B2C8\B2E4.</dd>'),
'            <dt>Marquee</dt>',
unistr('              <dd>\AE30\BCF8 \C815\BCF4\B97C \D3EC\D568\D558\B294 \C81C\BAA9 \D45C\C2DC\C904 \C601\C5ED\ACFC \CD95\C18C \AC00\B2A5\D55C \C624\B978\CABD \C5F4\C744 \C81C\ACF5\D569\B2C8\B2E4.'),
unistr('              \C774 \D398\C774\C9C0 \D15C\D50C\B9AC\D2B8\B294 \C5EC\B7EC \AD00\B828 \BCF4\ACE0\C11C \B610\B294 \B370\C774\D130\B97C \AC00\C9C4 \B2E8\C77C \B808\CF54\B4DC\B97C \D45C\C2DC\D558\B294 \B370 \C801\D569\D569\B2C8\B2E4.'),
unistr('              Marquee\B294 \BCF4\ACE0\C11C\C5D0\C11C \B2E8\C77C \B9C8\C2A4\D130 \B808\CF54\B4DC\B97C \CC98\C74C\C73C\B85C \C120\D0DD\D558\B294 \B9C8\C2A4\D130-\B514\D14C\C77C \AD00\ACC4\B97C \D45C\C2DC\D558\B294 \B370 \C77C\BC18\C801\C73C\B85C \C0AC\C6A9\B429\B2C8\B2E4. </dd>'),
unistr('            <dt>\CD5C\C18C(\D0D0\C0C9 \C5C6\C74C)</dt>'),
unistr('              <dd>\B9E4\C6B0 \AC04\B2E8\D55C \D398\C774\C9C0, \BD80\C778 \B610\B294 \B2E8\C77C \D398\C774\C9C0 \C560\D50C\B9AC\CF00\C774\C158\C774\B098 \D0D0\C0C9\C774 \D544\C694\D558\C9C0 \C54A\C740 \ACBD\C6B0\C5D0 \C720\C6A9\D569\B2C8\B2E4.</dd>'),
'          </dl>',
unistr('          \CC38\ACE0: <a rel="noopener noreferrer" target="_blank" href="https://apex.oracle.com/ut">\BC94\C6A9 \D14C\B9C8 \C0D8\D50C \C560\D50C\B9AC\CF00\C774\C158</a>'),
'        </p>'))
,p_version_scn=>2565330
);
