wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(113984825309665057)
,p_name=>'PE.PROPERTY.PAGE_WARN_ON_UNSAVED_CHANGES.COMPONENT_PROPERTY.PAGE.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C6F9 \D398\C774\C9C0\B97C \B514\C790\C778\D560 \B54C \B370\C774\D130 \C190\C2E4\C744 \BC29\C9C0\D558\B294 \AE30\B2A5\C744 \AD6C\D604\D558\C5EC \C0AC\C6A9\C790 \ACBD\D5D8\C744 \C6B0\C120\C2DC\D558\B294 \AC83\C774 \C911\C694\D569\B2C8\B2E4. \C800\C7A5\B418\C9C0 \C54A\C740 \BCC0\ACBD\C0AC\D56D\C5D0 \B300\D55C \D398\C774\C9C0 \ACBD\ACE0 \AE30\B2A5\C744 \C0AC\C6A9\C73C\B85C \C124\C815\D558\BA74 \C800\C7A5\B418\C9C0 \C54A\C740 \C218\C815\C0AC\D56D\C774 \D3EC\D568\B41C \D398\C774\C9C0\C5D0\C11C \B2E4\B978 \D398\C774\C9C0\B85C \C774\B3D9\D558\B824\ACE0 \C2DC\B3C4\D560 \B54C \C0AC\C6A9\C790\C5D0\AC8C \D1B5\C9C0\B429\B2C8\B2E4.'),
unistr('\C774 \AE30\B2A5\C740 \C720\C6A9\C131\C744 \D5A5\C0C1\C2DC\D0AC \BFD0\B9CC \C544\B2C8\B77C \B370\C774\D130 \BB34\ACB0\C131\ACFC \C0AC\C6A9\C790 \B9CC\C871\B3C4\B97C \BCF4\C7A5\D569\B2C8\B2E4.</p>')))
,p_version_scn=>2565248
);
wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(115503821805665505)
,p_name=>'PE.PROPERTY.PAGE_WARN_ON_UNSAVED_CHANGES.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\D398\C774\C9C0\C5D0 \C800\C7A5\B418\C9C0 \C54A\C740 \BCC0\ACBD\C0AC\D56D\C774 \C788\B294\B370 \D398\C774\C9C0\C5D0\C11C \B098\AC00\B824\ACE0 \D560 \B54C \C0AC\C6A9\C790\C5D0\AC8C \ACBD\ACE0\D560\C9C0 \C5EC\BD80\B97C \C9C0\C815\D569\B2C8\B2E4.'),
unistr('        \D398\C774\C9C0 \D56D\BAA9 \BC0F \B2E8\CD94\B3C4 \C774 \AC80\C0AC\AC00 \C5B8\C81C \C218\D589\B418\ACE0 \BB34\C5C7\C774 \D3EC\D568\B418\B294\C9C0\C5D0 \B300\D574 \B354\C6B1 \C138\BC00\D55C \C81C\C5B4\B97C \C81C\ACF5\D569\B2C8\B2E4.'),
unistr('        \B2E8\CD94\C758 \ACBD\C6B0 \B2E8\CD94\B97C \B204\B974\BA74 \AC80\C0AC\B97C \C218\D589\D558\B3C4\B85D \C9C0\C815\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('        \D398\C774\C9C0 \D56D\BAA9\C758 \ACBD\C6B0 \AC80\C0AC\C5D0\C11C \D56D\BAA9\C5D0 \B300\D55C \BCC0\ACBD\C0AC\D56D\C774 \D3EC\D568\B418\B294\C9C0 \B610\B294 \BB34\C2DC\B418\B294\C9C0 \C9C0\C815\D560 \C218 \C788\C2B5\B2C8\B2E4(\C774 \B458\C5D0 \B300\D574 <em>\C800\C7A5\B418\C9C0 \C54A\C740 \BCC0\ACBD\C0AC\D56D \ACBD\ACE0</em> \C18D\C131 \CC38\C870).</p>'),
unistr('        <p>\CC38\ACE0: \C774 \C124\C815\C740 \BAA8\B2EC \B300\D654\C0C1\C790 \D398\C774\C9C0\B97C \B2EB\C740 \C77C\BC18 \C0AC\C6A9\C790\C5D0\AC8C \C801\C6A9\B418\C9C0 \C54A\C2B5\B2C8\B2E4.</p>')))
,p_version_scn=>2565444
);
