,p_name=>'PE.PROPERTY.REGION_IMAGE_ALT_TEXT.COMPONENT_PROPERTY.REGION.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\B300\CCB4 \D14D\C2A4\D2B8\B294 \C2DC\AC01 \C7A5\C560\AC00 \C788\B294 \C0AC\C6A9\C790\C758 \C811\ADFC\C131\C744 \AC1C\C120\D558\B294 \C911\C694\D55C \C694\C18C\B85C \C0AC\C6A9\B429\B2C8\B2E4. \BB38\C11C \B610\B294 \C6F9 \D398\C774\C9C0 \B0B4 \C774\BBF8\C9C0\C758 \D14D\C2A4\D2B8 \C124\BA85\C744 \C81C\ACF5\D558\C5EC \CF58\D150\CE20\C640 \AD00\B828\B41C \C774\BBF8\C9C0\C758 \C911\C694\C131\C5D0 \B300\D55C \C778\C0AC\C774\D2B8\B97C \C81C\ACF5\D569\B2C8\B2E4.</p>'),
unistr('<strong>\CD5C\C801\C758 \BC29\BC95:</strong>'),
'<ol>',
unistr('<li>\BAA9\C801\C774 \C788\B294 \C124\BA85:'),
'<ul>',
unistr('<li>\B300\CCB4 \D14D\C2A4\D2B8\B294 \C8FC\BCC0 \CF58\D150\CE20\C640 \AD00\B828\B41C \C774\BBF8\C9C0\C758 \C911\C694\C131\C744 \AC04\ACB0\D558\AC8C \C804\B2EC\D574\C57C \D569\B2C8\B2E4.</li>'),
unistr('<li>\C774\BBF8\C9C0\AC00 \BB34\C5C7\C778\C9C0 \C124\BA85\D558\AE30\BCF4\B2E4\B294 \C774\BBF8\C9C0\C758 "\C774\C720"\B97C \C124\BA85\D558\B294 \B370 \C911\C810\C744 \B461\B2C8\B2E4.</li>'),
unistr('<li>\B300\CCB4 \D14D\C2A4\D2B8\B294 \BA85\D655\D558\ACE0 \AC04\ACB0\D558\BA70 \C124\BA85\C744 \D3EC\D568\D558\B3C4\B85D \C720\C9C0\D569\B2C8\B2E4.</li>'),
'</ul>',
'</li>',
unistr('<strong>\C608:</strong>'),
unistr('<p>"\B3C4\C804\C801\C778 \D504\B85C\C81D\D2B8\B97C \C131\ACF5\C801\C73C\B85C \C644\B8CC\D55C \D6C4 \D558\C774\D30C\C774\BE0C\D558\ACE0 \BBF8\C18C\B97C \C9C0\C73C\BA70 \CD95\D558\D558\B294 \D300"</p>'),
unistr('\C774 \C608\C5D0\C11C \B300\CCB4 \D14D\C2A4\D2B8\B294 \C774\BBF8\C9C0 \B4A4\C5D0 \C228\C740 \C774\C720, \C989 \B3C4\C804\C801\C778 \D504\B85C\C81D\D2B8\C758 \C131\ACF5\C801\C778 \C644\B8CC\C640 \ADF8\C5D0 \B530\B978 \D300\C6D0\B4E4 \AC04\C758 \CD95\D558\B97C \AC15\C870\D569\B2C8\B2E4. \C774 \C124\BA85\C740 \C774\BBF8\C9C0\B97C \C9C1\C811 \BCFC \C218 \C5C6\B294 \C0AC\C6A9\C790\C5D0\AC8C \C774\BBF8\C9C0\C758 \C911\C694\C131\C5D0 \B300\D55C \CEE8\D14D\C2A4\D2B8\C640 \C778\C0AC\C774\D2B8\B97C \C81C\ACF5\D569\B2C8\B2E4.'),
unistr('<li>\C720\C775\D55C \C774\BBF8\C9C0:'),
unistr('\C6F9 \D398\C774\C9C0\C5D0 \B300\D55C \C774\D574 \B610\B294 \CEE8\D14D\C2A4\D2B8\C5D0 \AE30\C5EC\D558\B294 \C774\BBF8\C9C0\B97C \C2DD\BCC4\D569\B2C8\B2E4.'),
unistr('\C774\BBF8\C9C0 \C81C\AC70 \C2DC \D398\C774\C9C0\C758 \C758\BBF8\B098 \C911\C694\C131\C774 \AC10\C18C\D558\B294 \ACBD\C6B0 \B300\CCB4 \D14D\C2A4\D2B8\AC00 \D544\C694\D569\B2C8\B2E4.</li>'),
unistr('<li>\C911\BCF5 \AD6C\BB38 \BC29\C9C0:'),
unistr('\C2A4\D06C\B9B0 \B9AC\B354\AC00 \C790\B3D9\C73C\B85C \D574\B2F9 \C774\BBF8\C9C0\B97C \D45C\C2DC\D558\BBC0\B85C "image of"\C640 \AC19\C740 \AD6C\BB38\C744 \C0DD\B7B5\D569\B2C8\B2E4.</li>'),
