,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p><p>\BCF4\ACE0\C11C \CEE8\D14C\C774\B108 \D15C\D50C\B9AC\D2B8\C5D0 \B300\D55C HTML \B9C8\D06C\C5C5\C744 \C785\B825\D569\B2C8\B2E4. "\BCF4\ACE0\C11C" \BC94\C704\C758 \C0AC\C6A9\C790\C815\C758 \C18D\C131\C5D0 \B300\D55C \C815\C801 ID\B294 <code>#STATIC_ID#</code> \AD6C\BB38\C5D0\C11C \CC38\C870\B420 \C218 \C788\C2B5\B2C8\B2E4.'),
unistr('<strong>\C18D\C131 \B3D9\AE30\D654</strong> \B2E8\CD94\B97C \C0AC\C6A9\D558\C5EC \BAA8\B4E0 \C704\CE58 \D45C\C2DC\C790\B97C \C0AC\C6A9\C790\C815\C758 \C18D\C131\C73C\B85C \BE60\B974\AC8C \B3D9\AE30\D654\D560 \C218 \C788\C2B5\B2C8\B2E4.'),
'</p>',
'<p>',
unistr('\B2E4\C74C\ACFC \AC19\C740 \BBF8\B9AC \C815\C758\B41C \D15C\D50C\B9AC\D2B8 \C704\CE58 \D45C\C2DC\C790\AC00 \C9C0\C6D0\B429\B2C8\B2E4.'),
'<dl>',
'<dt>APEX$DOM_ID</dt>',
unistr('<dd>\D15C\D50C\B9AC\D2B8\AC00 \D638\CD9C\B420 \B54C \C0DD\C131\B41C \ACE0\C720\D55C DOM ID\B85C, \C81C\ACF5\B41C HTML \B9C8\D06C\C5C5\C5D0\C11C \B2E4\B978 DOM \C694\C18C\B97C \CC38\C870\D558\B294 \B370 \C720\C6A9\D569\B2C8\B2E4.</dd>'),
'<dt>APEX$COMPONENT_CSS_CLASSES</dt>',
unistr('<dd>\C601\C5ED\C5D0 \B300\D574 \C9C0\C815\B41C CSS \D074\B798\C2A4\C785\B2C8\B2E4.</dd>'),
'<dt>APEX$REPORT_BODY</dt>',
unistr('<dd>\BCF4\ACE0\C11C \BCF8\BB38 \D15C\D50C\B9AC\D2B8\C758 \CD9C\B825\C785\B2C8\B2E4.</dd>'),
'</dl>',
'</p>',
unistr('<p>\C2AC\B86F \C704\CE58 \D45C\C2DC\C790\B97C \C0AC\C6A9\D558\BA74 \C774 \BCF4\ACE0\C11C \CEE8\D14C\C774\B108\AC00 \D398\C774\C9C0 \AD6C\C131\C694\C18C(\C601\C5ED, \D56D\BAA9, \B2E8\CD94)\B97C \B80C\B354\B9C1\D560 \C218\B3C4 \C788\C2B5\B2C8\B2E4.<br /> \C2AC\B86F\C740 <code>#SLOT_STATIC_ID#</code> \AD6C\BB38\C73C\B85C \CC38\C870\D560 \C218 \C788\C2B5\B2C8\B2E4.<br />'),
unistr('\C0AC\C6A9\BC95\C5D0 \B530\B77C \C870\AC74\BD80\B85C \C2AC\B86F\C744 \B80C\B354\B9C1\D558\B824\BA74 <code>{if SLOT_STATIC_ID/}&lt;div class="inner-div"&gt;#SLOT_STATIC_ID#&lt;/div&gt;{endif/}</code> \AD6C\BB38\C744 \C0AC\C6A9\D558\C5EC \C2AC\B86F\C774 \C0AC\C6A9 \C911\C778 \ACBD\C6B0\C5D0\B9CC \CD94\AC00 \B9C8\D06C\C5C5\C744 \B80C\B354\B9C1\D569\B2C8\B2E4.<br />'),
unistr('\BCF4\ACE0\C11C \CEE8\D14C\C774\B108 \D15C\D50C\B9AC\D2B8\C758 \C2AC\B86F\C740 \C5F0\AD00\B41C \C601\C5ED\C774 <strong>\D45C\C2DC \D615\C2DD: \B2E4\C911(\BCF4\ACE0\C11C)</strong>\B97C \C0AC\C6A9\D558\B294 \ACBD\C6B0\C5D0\B9CC \B80C\B354\B9C1\B429\B2C8\B2E4.</p>'),
