,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C5F4 \BA38\B9AC\AE00\C740 \D45C \D615\C2DD\C758 \B370\C774\D130\B97C \BA85\D655\D558\ACE0 \C774\D574\D558\AE30 \C26C\C6B4 \D615\C2DD\C73C\B85C \AD6C\C131\D558\ACE0 \D45C\C2DC\D558\B294 \B370 \C911\C694\D55C \C5ED\D560\C744 \D569\B2C8\B2E4.</p>'),
unistr('<strong>\CD5C\C801\C758 \BC29\BC95:</strong>'),
'<ol>',
unistr('<li><strong>\C124\BA85\C744 \D3EC\D568\D558\BA70 \C758\BBF8 \C788\C74C:</strong> \AC01 \C5F4\C758 \CF58\D150\CE20\AC00 \C815\D655\D558\AC8C \B098\D0C0\B098\B3C4\B85D \C124\BA85\C744 \D3EC\D568\D558\BA70 \C758\BBF8 \C788\B294 \C5F4 \BA38\B9AC\AE00\C744 \C0AC\C6A9\D569\B2C8\B2E4. \C5F4 \BA38\B9AC\AE00\C740 \D574\B2F9 \C5F4 \B0B4\C5D0 \D3EC\D568\B41C \C815\BCF4\B97C \AC04\ACB0\D558\AC8C \C804\B2EC\D574\C57C \D569\B2C8\B2E4.</li>'),
unistr('<li><strong>\C77C\AD00\C131:</strong> \D14C\C774\BE14 \C804\CCB4\C5D0\C11C \C5F4 \BA38\B9AC\AE00\C758 \C77C\AD00\C131\C744 \C720\C9C0\D569\B2C8\B2E4. \C77C\AD00\B41C \C5F4 \BA38\B9AC\AE00\C740 \D2B9\D788 \C5EC\B7EC \C5F4\C774 \D3EC\D568\B41C \BCF5\C7A1\D55C \D14C\C774\BE14\ACFC \C0C1\D638\C791\C6A9\D560 \B54C \C0AC\C6A9\C790\C758 \D0D0\C0C9 \BC0F \C774\D574\B97C \C6A9\C774\D558\AC8C \D569\B2C8\B2E4.</li>'),
'</ol>'))
