wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(115189288118665412)
,p_name=>'PE.PROPERTY.REPORT_TEMPLATE.HELP'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C774 \D074\B798\C2DD \BCF4\ACE0\C11C\C758 \BAA8\C591\ACFC \B808\C774\C544\C6C3\C744 \C815\C758\D560 \BCF4\ACE0\C11C \D15C\D50C\B9AC\D2B8\B97C \C120\D0DD\D569\B2C8\B2E4.</p>'),
unistr('        <p>\BCF4\ACE0\C11C \D15C\D50C\B9AC\D2B8\B294 \C560\D50C\B9AC\CF00\C774\C158 \D14C\B9C8\C5D0\C11C \C815\C758\B429\B2C8\B2E4.'),
unistr('        \D074\B798\C2DD \BCF4\ACE0\C11C\AC00 \C0DD\C131\B418\BA74 \D15C\D50C\B9AC\D2B8\B294 \D604\C7AC \D14C\B9C8\C5D0 \C815\C758\B41C \AE30\BCF8 \BCF4\ACE0\C11C \D15C\D50C\B9AC\D2B8\B85C \C790\B3D9\C73C\B85C \C124\C815\B429\B2C8\B2E4.</p>'),
unistr('        <p>\B300\BD80\BD84\C758 \D14C\B9C8\C5D0\B294 \D14C\C774\BE14, \D0A4 \AC12 \C30D, \AC80\C0C9 \ACB0\ACFC, \CE74\B4DC \B4F1\C5D0\C11C \B370\C774\D130\B97C \D45C\C2DC\D558\AE30 \C704\D55C \D074\B798\C2DD \BCF4\ACE0\C11C \D15C\D50C\B9AC\D2B8\AC00 \D3EC\D568\B418\C5B4 \C788\C2B5\B2C8\B2E4.'),
unistr('        \C77C\BD80 \BCF4\ACE0\C11C \D15C\D50C\B9AC\D2B8(\C608: \CE74\B4DC \BC0F \AC80\C0C9 \ACB0\ACFC)\B294 "\D589 \AE30\BC18"\C774\BA70, SQL \C9C8\C758\AC00 \D15C\D50C\B9AC\D2B8\C5D0\C11C \B300\CCB4\B418\B294 \C77C\B828\C758 \D2B9\C815 \C5F4 \BCC4\CE6D\C744 \BC18\D658\D574\C57C \D569\B2C8\B2E4.<br>'),
unistr('        \BC94\C6A9 \D14C\B9C8\B294 \B2E4\C74C\ACFC \AC19\C740 \BCF4\ACE0\C11C \D15C\D50C\B9AC\D2B8\B97C \C81C\ACF5\D569\B2C8\B2E4.'),
'          <dl>',
unistr('            <dt>\ACBD\BCF4</dt>'),
unistr('              <dd>\D398\C774\C9C0\C5D0 \C6D0\D558\B294 \C218\C758 \AC00\B85C \ACBD\BCF4 \B610\B294 \D1B5\C9C0\B97C \D45C\C2DC\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\BC30\C9C0 \BAA9\B85D</dt>'),
unistr('              <dd>\B300\C2DC\BCF4\B4DC\C640 \C720\C0AC\D55C \C0AC\C6A9\C790 \C778\D130\D398\C774\C2A4\C5D0 \D0A4 \AC12 \C30D\C744 \D45C\C2DC\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\CE74\B4DC</dt>'),
unistr('              <dd>\CE74\B4DC \B610\B294 \C791\C740 \BE14\B85D\C5D0 \BCF4\ACE0\C11C \B370\C774\D130\B97C \D45C\C2DC\D558\BA70 \B2E4\C591\D55C \C815\BCF4\B97C \B098\D0C0\B0B4\B294 \B370 \C720\C6A9\D569\B2C8\B2E4. \D15C\D50C\B9AC\D2B8 \C635\C158\C744 \D1B5\D574 \CE74\B4DC\B97C \C0AC\C6A9\C790\AC00 \C815\C758\D560 \C218 \C788\C2B5\B2C8\B2E4.</dd>'),
unistr('            <dt>\C124\BA85</dt>'),
unistr('              <dd>\C124\BA85 \BC0F \AE30\D0C0 \BA54\C2DC\C9C0\B97C \D45C\C2DC\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\CF58\D150\CE20 \D589</dt>'),
unistr('              <dd>\C120\D0DD \C5F4, \C544\C774\CF58 \BC0F \C791\C5C5\C744 \C9C0\C6D0\D558\C5EC \BCF4\ACE0\C11C \B370\C774\D130\B97C \C77C\B828\C758 \D589\C73C\B85C \D45C\C2DC\D569\B2C8\B2E4. \B300\BD80\BD84\C758 \CF58\D150\CE20 \C720\D615\C5D0 \C801\D569\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\CEE8\D14D\C2A4\D2B8 \C815\BCF4</dt>'),
unistr('              <dd>\AC04\B2E8\D55C \D0A4-\AC12 \C30D\C744 \CC28\B840\B85C \D45C\C2DC\D569\B2C8\B2E4. \C5F4 \BA38\B9AC\AE00\C744 \B808\C774\BE14\B85C \C0AC\C6A9\D558\ACE0 \AC01 \B808\C774\BE14 \C606\C5D0 \C5F0\AD00\B41C \C5F4 \AC12\C744 \D45C\C2DC\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\B9E4\CCB4 \BAA9\B85D</dt>'),
unistr('              <dd>\C544\C774\CF58, \BA38\B9AC\AE00, \C124\BA85 \BC0F \BC30\C9C0\C640 \D568\AED8 \B9E4\CCB4 \BAA9\B85D\C5D0 \BCF4\ACE0\C11C \CF58\D150\CE20\B97C \D45C\C2DC\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\AC80\C0C9 \ACB0\ACFC</dt>'),
unistr('              <dd>\AC80\C0C9 \C5D4\C9C4 \C2A4\D0C0\C77C \AC80\C0C9 \ACB0\ACFC\B97C \D45C\C2DC\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\D45C\C900</dt>'),
unistr('              <dd>\D14C\C774\BE14\C5D0 \B370\C774\D130\B97C \D45C\C2DC\D558\AE30 \C704\D55C \AE30\BCF8 \BCF4\ACE0\C11C \D15C\D50C\B9AC\D2B8\C774\BA70 \D15C\D50C\B9AC\D2B8 \C635\C158\C744 \D1B5\D574 \C0AC\C6A9\C790\AC00 \C815\C758\D560 \C218 \C788\C2B5\B2C8\B2E4.</dd>'),
unistr('            <dt>\D0C0\C784\B77C\C778</dt>'),
unistr('              <dd>\C791\C5C5 \D0C0\C784\B77C\C778\C744 \D45C\C2DC\D558\BA70, \CD5C\ADFC \C791\C5C5\C5D0 \B300\D55C \C791\C5C5 \D53C\B4DC\AC00 \D544\C694\D55C \D648 \D398\C774\C9C0, \BCC0\ACBD \B85C\ADF8 \BC0F \AE30\D0C0 \C601\C5ED\C5D0 \C801\D569\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\AC12 \C18D\C131 \C30D - \C5F4</dt>'),
unistr('              <dd>\C5F4 \AE30\BC18 \C9C8\C758\C5D0 \B300\D55C \D0A4-\AC12 \C30D\C744 \D45C\C2DC\D558\BA70, \C5F4 \BA38\B9AC\AE00\C744 \AC01 \D56D\BAA9\C5D0 \B300\D55C \B808\C774\BE14\B85C \C0AC\C6A9\D569\B2C8\B2E4.</dd>'),
unistr('            <dt>\AC12 \C18D\C131 \C30D - \D589</dt>'),
unistr('              <dd>\D589 \AE30\BC18 \C9C8\C758\C5D0 \B300\D55C \D0A4-\AC12 \C30D\C744 \D45C\C2DC\D558\BA70, \B808\C774\BE14\C5D0 \B300\D574 \CCAB\BC88\C9F8 \C5F4\C744 \C0AC\C6A9\D558\ACE0 \AC12\C5D0 \B300\D574 \B450\BC88\C9F8 \B808\C774\BE14\C744 \C0AC\C6A9\D569\B2C8\B2E4.</dd>'),
'          </dl>',
unistr('          \CC38\C870: <a rel="noopener noreferrer" target="_blank" href="https://apex.oracle.com/ut">\BC94\C6A9 \D14C\B9C8 \C0D8\D50C \C560\D50C\B9AC\CF00\C774\C158</a>'),
'        </p>'))
,p_version_scn=>2565400
);
