,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
'',
unistr('<p>Oracle Text \C9C8\C758 \AD6C\BB38\C740 \B9E4\C6B0 \BCF5\C7A1\D558\ACE0 \AC15\B825\D558\BA70 \C640\C77C\B4DC \CE74\B4DC \BB38\C790, \C2A4\D0DC\BC0D, \C720\C0AC \AC80\C0C9 \B4F1\C744 \CC98\B9AC\D560 \C218 \C788\B294 \B2E4\C591\D55C \C9C8\C758 \C5F0\C0B0\C790\B97C \C81C\ACF5\D569\B2C8\B2E4. \C77C\BC18 \C0AC\C6A9\C790\C758 \ACBD\C6B0 \C774 \AD6C\BB38\C744 \C774\D574\D558\AE30 \C5B4\B824\C6B8 \C218\B3C4 \C788\C2B5\B2C8\B2E4. \C0AC\C6A9\C790\C758 \AC80\C0C9 \D504\B85C\C138\C2A4\B97C \AC04\C18C\D654\D558\AE30 \C704\D574 \AC04\B2E8\D55C \C77C\BC18 \C0AC\C6A9\C790 \C785\B825\C744 Oracle Text \C9C8\C758\B85C \C790\B3D9\C73C\B85C \BCC0\D658\D558\B294 \D568\C218\B97C \C120\D0DD\D560 \C218 \C788\C2B5\B2C8\B2E4. \C774\B54C \ACE0\AE09 \AC80\C0C9 \AE30\B2A5\C740 \C790\B3D9\C73C\B85C \C801\C6A9\B429\B2C8\B2E4. \C0AC\C6A9\D560 \D14D\C2A4\D2B8 \C9C8\C758 \D568\C218 \C720\D615\C744 \C120\D0DD\D569\B2C8')
||unistr('\B2E4.')))
,p_version_scn=>2565272
);
