,p_name=>'PE.PROPERTY.TEXT_QUERY_FUNCTION_TYPE.LOV.EXPERT_SEARCH.HELP'
,p_message_language=>'ko'
,p_message_text=>unistr('\C774 \D568\C218\B294 \C815\AD50\D55C \C9C8\C758\B97C \C704\D574 \ACE0\AE09 \AC80\C0C9 \C5F0\C0B0\C790\B97C \C9C0\C6D0\D569\B2C8\B2E4. \C815\D655\D55C \C77C\CE58, \BD80\C6B8 \C5F0\C0B0\C790(AND, OR, NOT), \AD04\D638\B97C \C0AC\C6A9\D55C \C6B0\C120\C21C\C704, \ADFC\C811 \AC80\C0C9\C774 \D5C8\C6A9\B429\B2C8\B2E4. \CD94\AC00 \B9E4\AC1C\BCC0\C218\B97C \C0AC\C6A9\D558\C5EC \AC80\C0C9 \B3D9\C791\C744 \C0AC\C6A9\C790\C815\C758\D560 \C218 \C788\C2B5\B2C8\B2E4. \C774 \BC29\C2DD\C740 \B9E4\C6B0 \AD6C\CCB4\C801\C778 \C9C8\C758\C5D0\C11C \AC00\C7A5 \C815\D655\D55C \ACB0\ACFC\AC00 \D544\C694\D560 \B54C \AC00\C7A5 \C801\D569\D569\B2C8\B2E4. <code>APEX_SEARCH</code> \D328\D0A4\C9C0 \B0B4\C758 <code>QUERY_EXPERT_SEARCH</code> \D568\C218\B97C \CC38\C870\D558\C2ED\C2DC\C624')
||'.'
,p_version_scn=>2565272
);
