,p_message_language=>'ko'
,p_message_text=>unistr('\CD95\C5D0 \B300\D55C \C81C\BAA9\C744 \C785\B825\D569\B2C8\B2E4. \C774 \C81C\BAA9\C740 \CC28\D2B8\C758 \CD95\C5D0 \D45C\C2DC\B418\B294 \C815\BCF4\B97C \C124\BA85\D569\B2C8\B2E4.')
