wwv_flow_imp_shared.create_message(
 p_id=>wwv_flow_imp.id(113984613309665057)
,p_name=>'PE.PROPERTY.TITLE.COMPONENT_PROPERTY.PAGE.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\D398\C774\C9C0 \C81C\BAA9\C740 \BAA8\B4E0 \C0AC\C6A9\C790, \D2B9\D788 \C2A4\D06C\B9B0 \B9AC\B354\C640 \AC19\C740 \BCF4\C870 \AE30\C220\C744 \C774\C6A9\D558\B294 \C0AC\C6A9\C790\AC00 \D398\C774\C9C0\C758 \C6A9\B3C4\B97C \D30C\C545\D560 \C218 \C788\B3C4\B85D \D574\C8FC\B294 \B370 \C911\C694\D569\B2C8\B2E4. \D398\C774\C9C0 \C81C\BAA9\C740 \C2A4\D06C\B9B0 \B9AC\B354 \C0AC\C6A9\C790\AC00 \AC00\C7A5 \BA3C\C800 \B4E3\B294 \B0B4\C6A9\C778 \ACBD\C6B0\AC00 \B9CE\C73C\BBC0\B85C \BAA8\B4E0 \D398\C774\C9C0 \C81C\BAA9\C740 \C758\BBF8 \C788\ACE0 \ACE0\C720\D574\C57C \D569\B2C8\B2E4.</p>'),
unistr('<p>\CD5C\C801\C758 \BC29\BC95:</p>'),
'<ol>',
unistr('<li>\BA85\D655\D558\ACE0 \C124\BA85 \D3EC\D568:'),
unistr('\C26C\C6B4 \D0D0\C0C9\C744 \C704\D574 "WCAG 2.1 \C774\D574"\C640 \AC19\C740 \D2B9\C815 \C81C\BAA9\C774\B098 \C139\C158 \C81C\BAA9\C744 \C0AC\C6A9\D569\B2C8\B2E4.</li>'),
unistr('<li>\D6A8\ACFC\C801:'),
unistr('\C608\B97C \B4E4\C5B4, \D3FC \D398\C774\C9C0\C758 \ACBD\C6B0 "\ACE0\AC1D \C0DD\C131/\D3B8\C9D1: [\ACE0\AC1D \C774\B984]" \B4F1 \D3B8\C9D1 \C911\C778 \B808\CF54\B4DC\C640 \AC19\C740 \AD00\B828 \C815\BCF4\B97C \D3EC\D568\D558\B294 \AC83\C774 \C88B\C2B5\B2C8\B2E4. \D398\C774\C9C0 \B514\C790\C774\B108\C5D0\C11C \B2E4\C74C \B2E8\ACC4\B97C \B530\B985\B2C8\B2E4.'),
'<ol>',
unistr('<li>\B80C\B354\B9C1 \D2B8\B9AC\C5D0\C11C \D398\C774\C9C0\B97C \C120\D0DD\D569\B2C8\B2E4.</li>'),
unistr('<li>\C18D\C131 \D3B8\C9D1\AE30\C5D0\C11C \C2DD\BCC4 - \C81C\BAA9 \D544\B4DC\B97C \CC3E\C2B5\B2C8\B2E4.</li>'),
unistr('<li>P1_CUSTOMER_NAME\C744 \B808\CF54\B4DC \C2DD\BCC4\C790\AC00 \D3EC\D568\B41C \C801\C808\D55C \D398\C774\C9C0 \D56D\BAA9\C73C\B85C \BC14\AFC9\B2C8\B2E4.</li>'),
unistr('<li>&P1_CUSTOMER_NAME.(\B9C8\CE68\D45C \D3EC\D568) \ACE0\AC1D \C0DD\C131/\D3B8\C9D1\C73C\B85C \C81C\BAA9 \D615\C2DD\C744 \C785\B825\D569\B2C8\B2E4.</li>'),
'</ol>',
'</li>',
'</ol>',
unistr('<p>\C124\BA85\C774 \D3EC\D568\B41C \D398\C774\C9C0 \BC0F \C601\C5ED \C81C\BAA9\C744 \AD6C\D604\D558\BA74 \C811\ADFC\C131\C774 \D06C\AC8C \D5A5\C0C1\B418\C5B4 \B2E4\C591\D55C \C6F9 \D658\ACBD\C5D0\C11C \C0AC\C6A9\C790\AC00 \C6D0\D65C\D558\AC8C \D0D0\C0C9\D558\ACE0 \CF58\D150\CE20\B97C \C774\D574\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>')))
,p_version_scn=>2565248
);
