,p_name=>'PE.PROPERTY.USE_AS_ROW_HEADER.COMPONENT_PROPERTY.CLASSIC_REPORT_COLUMN.ACCESSIBILITY_HELP_TEXT'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C2A4\D06C\B9B0 \B9AC\B354\C640 \AC19\C740 \BCF4\C870 \AE30\C220 \C0AC\C6A9\C790\C758 \C720\C6A9\C131\C744 \AC1C\C120\D558\B824\BA74 \D45C \D615\C2DD \BCF4\ACE0\C11C \B370\C774\D130(\C608: \D074\B798\C2DD \B610\B294 \B300\D654\C2DD \BCF4\ACE0\C11C)\C5D0 \B300\D55C \D589 \BA38\B9AC\AE00\C744 \C815\C758\D574\C57C \D569\B2C8\B2E4.</p>'),
unistr('<strong>\CD5C\C801\C758 \BC29\BC95:</strong>'),
'<ol>',
unistr('<li><strong>\C2A4\D06C\B9B0 \B9AC\B354 \C0AC\C6A9\C790\C758 \C720\C6A9\C131\C5D0 \B07C\CE58\B294 \C601\D5A5:</strong>'),
'<ul>',
unistr('<li>\C2A4\D06C\B9B0 \B9AC\B354 \C0AC\C6A9\C790\AC00 \BCF4\ACE0\C11C\C758 \C5EC\B7EC \D589\C744 \D0D0\C0C9\D560 \B54C \C0C8 \D589\C73C\B85C \C774\B3D9\D558\BA74 \D589\C744 \C2DD\BCC4\D558\B294 \AC83\C73C\B85C \C9C0\C815\B41C \C5F4\C774 \D589 \BA38\B9AC\AE00\B85C \D45C\C2DC\B429\B2C8\B2E4.</li>'),
unistr('<li>\D589 \BA38\B9AC\AE00 \C5F4 \C815\C758\B97C \C2E4\D328\D558\BA74 \C2A4\D06C\B9B0 \B9AC\B354 \C0AC\C6A9\C790\AC00 \BCF4\ACE0\C11C\B97C \D0D0\C0C9\D558\B294 \B3D9\C548 \BC29\D5A5\C744 \C7A1\B294 \AC83\C774 \D6E8\C52C \B354 \C5B4\B824\C6CC\C9D1\B2C8\B2E4.</li>'),
'</ul>',
'</li>',
unistr('<li><strong>\BC29\D5A5 \BC0F \D0D0\C0C9 \AC1C\C120:</strong>'),
'<ul>',
unistr('<li>\C774 \C18D\C131\C744 \C815\C758\D558\BA74 \D45C \D615\C2DD \B370\C774\D130 \B0B4\C5D0\C11C \BA85\D655\D55C \BC29\D5A5 \C9C0\C810\C744 \C81C\ACF5\D558\C5EC \C2A4\D06C\B9B0 \B9AC\B354 \C0AC\C6A9\C790\C758 \D0D0\C0C9 \D658\ACBD\C774 \D5A5\C0C1\B429\B2C8\B2E4.</li>'),
unistr('<li>\C774\B97C \D1B5\D574 \BCF4\C870 \AE30\C220\C744 \C774\C6A9\D558\B294 \C0AC\C6A9\C790\AC00 \BCF4\B2E4 \C6D0\D65C\D558\AC8C \D0D0\C0C9\C744 \C218\D589\D558\ACE0 \BCF4\ACE0\C11C \B0B4\C6A9\C744 \C774\D574\D560 \C218 \C788\C2B5\B2C8\B2E4.</li>'),
'</ul>',
'</li>',
unistr('<li><strong>\AD8C\C7A5\C0AC\D56D:</strong>'),
'<ul>',
unistr('<li>\BCF4\C870 \AE30\C220 \C0AC\C6A9\C790\B97C \C704\D55C \D589 \BA38\B9AC\AE00\B85C \C0AC\C6A9\B420 \D589 \C2DD\BCC4 \C5F4\C744 \D558\B098 \C774\C0C1 \C815\C758\D569\B2C8\B2E4.</li>'),
unistr('<li>\C774\B294 \C0AC\C6A9\C790\AC00 \D589 \C0AC\C774\B97C \C774\B3D9\D560 \B54C\B9C8\B2E4 \D45C\C2DC\B418\BBC0\B85C \C804\CCB4 \D589 \BA38\B9AC\AE00\C774 \B108\BB34 \AE38\C5B4\C11C \C9C0\B098\CE58\AC8C \C7A5\D669\D574\C9C0\C9C0 \C54A\B3C4\B85D \D574\C57C \D569\B2C8\B2E4.</li>'),
'</ul>',
'</li>',
'</ol>'))
,p_version_scn=>2565249
);
