,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\B79C\B4DC\B9C8\D06C\B294 \C6F9 \D398\C774\C9C0\C758 \AD6C\C131\ACFC \AD6C\C870\B97C \C2DD\BCC4\D558\B294 \AC15\B825\D55C \BC29\BC95\C744 \C81C\ACF5\D569\B2C8\B2E4. \C0AC\C6A9\C790\C5D0\AC8C \C2DC\AC01\C801\C73C\B85C \C804\B2EC\B418\B294 \AD6C\C870\C801 \C815\BCF4\B294 \B79C\B4DC\B9C8\D06C \B864\C744 \C0AC\C6A9\D558\C5EC \B9C8\D06C\C5C5\C5D0\C11C \D504\B85C\ADF8\B798\BC0D \BC29\C2DD\C73C\B85C \D45C\D604\B418\C5B4\C57C \D569\B2C8\B2E4. \B79C\B4DC\B9C8\D06C \B864\C744 \C0AC\C6A9\D558\BA74 \C2A4\D06C\B9B0 \B9AC\B354 \C0AC\C6A9\C790\AC00 \C6F9 \D398\C774\C9C0\C758 \AD6C\C870\B97C \D0A4\BCF4\B4DC \D0D0\C0C9\D560 \C218 \C788\C73C\BA70, \D5A5\C0C1\B41C \D0A4\BCF4\B4DC \D0D0\C0C9\C744 \C704\D55C \BE0C\B77C\C6B0\C800 \D655\C7A5 \B300\C0C1\C73C\B85C \C0AC\C6A9\B420 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
unistr('    <p>\B79C\B4DC\B9C8\D06C\B97C \C0AC\C6A9\D560 \B54C \BAA8\B4E0 \C778\C2DD \AC00\B2A5\D55C \CF58\D150\CE20(\C608: APEX \C571\C758 \BAA8\B4E0 \D56D\BAA9, \B2E8\CD94, \C601\C5ED, \BA54\B274 \B4F1)\AC00 \B79C\B4DC\B9C8\D06C\C5D0 \D3EC\D568\B418\C5B4\C57C \C0AC\C6A9\C790\AC00 \CF58\D150\CE20\B97C \B193\CE58\C9C0 \C54A\C744 \C218 \C788\C2B5\B2C8\B2E4. \B79C\B4DC\B9C8\D06C \B808\C774\BE14\C744 \C9C0\C815\D560 \B54C \C601\C5ED \C81C\BAA9\C744 \C0AC\C6A9\D558\AC70\B098(\AE30\BCF8\AC12), \C601\C5ED\C5D0 \C0AC\C6A9\C790\C815\C758 \B79C\B4DC\B9C8\D06C \B808\C774\BE14\C744 \C815\C758\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>')))
,p_version_scn=>2565257
);
