,p_name=>'USER_TYPE_DESCRIPTION'
,p_message_language=>'ko'
,p_message_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C774 \D398\C774\C9C0\C5D0\C11C\B294 Oracle APEX \C791\C5C5\C601\C5ED \AD00\B9AC\C790, \C560\D50C\B9AC\CF00\C774\C158 \AC1C\BC1C\C790 \BC0F \C77C\BC18 \C0AC\C6A9\C790\C5D0 \B300\D55C \C561\C138\C2A4\B97C \C81C\C5B4\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
'',
unistr('<p><strong>\C791\C5C5\C601\C5ED \AD00\B9AC\C790</strong>\B294 \C560\D50C\B9AC\CF00\C774\C158 \BC0F \B370\C774\D130\BCA0\C774\C2A4 \AC1D\CCB4\B97C \C0DD\C131 \BC0F \C218\C815\D558\ACE0, \C0AC\C6A9\C790 \ACC4\C815, \ADF8\B8F9 \BC0F \AC1C\BC1C \C11C\BE44\C2A4\B97C \AD00\B9AC\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
'',
unistr('<p><strong>\AC1C\BC1C\C790</strong>\B294 \C560\D50C\B9AC\CF00\C774\C158 \BC0F \B370\C774\D130\BCA0\C774\C2A4 \AC1D\CCB4\B97C \C0DD\C131 \BC0F \C218\C815\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
'',
unistr('<p><strong>\C77C\BC18 \C0AC\C6A9\C790</strong>\B294 \AC1C\BC1C \AD8C\D55C\C774 \C5C6\C73C\BA70 \C678\BD80 \C778\C99D \CCB4\ACC4\B97C \C0AC\C6A9\D558\C9C0 \C54A\B294 \C560\D50C\B9AC\CF00\C774\C158\B9CC \C561\C138\C2A4\D560 \C218 \C788\C2B5\B2C8\B2E4.</p>'),
'',
unistr('<p><a target="_blank" href="%0/aeadm/managing-users-in-a-workspace.html">\C790\C138\D788...</a></p>'),
''))
,p_version_scn=>2565288
);
