,p_display_sequence=>20
,p_display_value=>unistr('APEX_APPLICATION_TEMP_FILES \D14C\C774\BE14')
,p_return_value=>'APEX_APPLICATION_TEMP_FILES'
,p_help_text=>wwv_flow_string.join(wwv_flow_t_varchar2(
unistr('<p>\C5C5\B85C\B4DC\B41C \D30C\C77C\C744 APEX_APPLICATION_TEMP_FILES. \BDF0\B85C \C561\C138\C2A4\D560 \C218 \C788\B294 \C784\C2DC \C704\CE58\C5D0 \C800\C7A5\D569\B2C8\B2E4. &PRODUCT_NAME.\C740(\B294) <strong>\B2E4\C74C\C5D0 \D30C\C77C \BE44\C6B0\AE30</strong>\C5D0\C11C \C0AC\C6A9\C790\AC00 \C120\D0DD\D55C \D56D\BAA9\C5D0 \B530\B77C \C138\C158 \C885\B8CC \C2DC \B610\B294 \C5C5\B85C\B4DC \C694\CCAD \C885\B8CC \C2DC \C790\B3D9\C73C\B85C \D574\B2F9 \D30C\C77C\C744 \C0AD\C81C\D569\B2C8\B2E4.</p>'),
unistr('<p><strong>\B2E4\C911 \D30C\C77C \D5C8\C6A9</strong>\C774 <strong>\C544\B2C8\C624</strong>\B85C \C124\C815\B41C \ACBD\C6B0 \D30C\C77C\C5D0 \C561\C138\C2A4\D558\B824\BA74 \B2E4\C74C\C744 \C0AC\C6A9\D558\C2ED\C2DC\C624.</p>'),
'<pre>',
'select *',
'  from apex_application_temp_files',
' where name = :<em>page item name</em>;',
'</pre>',
unistr('<p><strong>\B2E4\C911 \D30C\C77C \D5C8\C6A9</strong>\C774 <strong>\C608</strong>\B85C \C124\C815\B41C \ACBD\C6B0 \D30C\C77C\C5D0 \C561\C138\C2A4\D558\B824\BA74 \B2E4\C74C\C744 \C0AC\C6A9\D558\C2ED\C2DC\C624.</p>'),
'<pre>',
'declare',
'    l_file_names apex_t_varchar2;',
'    l_file       apex_application_temp_files%rowtype;',
'begin',
'    l_file_names := apex_string.split (',
'                        p_str => :<em>page item name</em>,',
'                        p_sep => '':'' );',
'    for i in 1 .. l_file_names.count loop',
'        select *',
'          into l_file',
'          from apex_application_temp_files',
'         where name = l_file_names(i);',
'        -- add code here to store the uploaded file in your own table',
'    end loop;',
'end;',
'</pre>'))
);
